        try {
            Pokemon pokemon = apiClient.getPokemon(name);
            TypeEffectiveness effectiveness = apiClient.getTypeEffectiveness(pokemon.getTypes());
            // ... other processing ...
        } catch (ExternalApiException e) {
            return ResponseEntity.status(e.getStatusCode()).body(new ErrorResponse(e));
        } catch (InvalidPokemonNameException e) {
            return ResponseEntity.badRequest().body(new ErrorResponse(e));
        }
