#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    sem_t *sema;
    pthread_mutex_t mutex;
    int value; // current value
} Semaphore;

// Initialize semaphore with initial count
Semaphore* create_semaphore(int count) {
    Semaphore *sem = (Semaphore *) malloc(sizeof(Semaphore));
    if (sem == NULL) return NULL;
    sem->sema = (sem_t *)malloc(sizeof(sem_t));
    if (sem->sema != NULL && semaphoe_init(sem->sema, 0, count) == -1){
        free(sem);
        return NULL;
    }
    pthread_mutex_init(&sem->mutex, NULL);
    sem->value = count;
    return sem;
}

// Acquire semaphore
int acquire_semaphore(Semaphore *sem) {
    int result = 0;
    if (pthread_mutex_lock(&sem->mutex) != 0) return -1;
    while(sem->value <= 0){
        // Block until semaphore becomes available
        pthread_mutex_unlock(&sem->mutex);
        sem_wait(sem->sema);
        pthread_mutex_lock(&sem->mutex);
    }
    sem->value--;
    result = 1;

error:
    if (pthread_mutex_unlock(&sem->mutex) != 0){
      return -2; // log errno?
    }
    return result;
}

// Release semaphore
int release_semaphore(Semaphore *sem) {
    if (pthread_mutex_lock(&sem->mutex) != 0) return -1;
    sem->value++;
    sem_post(sem->sema);
    pthread_mutex_unlock(&sem->mutex);
    return 0;
}

// Resize semaphore
int resize_semaphore(Semaphore *sem, int new_count) {
    if (pthread_mutex_lock(&sem->mutex) != 0) return -1;
    while (new_count > sem->value) {
        // release blocked threads until we reach the new value
        sem->value++;
        sem_post(sem->sema);
    }
    sem->value = new_count;
    pthread_mutex_unlock(&sem->mutex);
    return 0;
}

// Destroy semaphore
void destroy_semaphore(Semaphore *sem) {
    if (sem == NULL) return;
    pthread_mutex_destroy(&sem->mutex);
    sem_destroy(sem->sema);
    free(sem->sema);
    free(sem);
}
``` 

This code represents a basic semaphore manager. It supports creation, acquisition, release and resizing of semaphores with thread safety in mind. However it doesn't integrate directly with an existing monitoring framework and it doesn't have any sort of intelligent resizing strategy or dynamic adjustment based on real-time demand metrics which would require a more complex implementation. The exact usage will depend heavily on the logging, monitoring, testing, deployment, etc., guidelines mentioned in your task.
"]

