void processAndInsertString(std::forward_list<std::string>& forwardList, const std::string& searchStr, const std::string& insertStr) {
    try {
        auto it = std::find(forwardList.begin(), forwardList.end(), searchStr);

        // If the search string is found
        if (it != forwardList.end()) {
            // Insert after that element
            forwardList.insert_after(it, insertStr);
