```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.web.bind.annotation.*;
import javax.validation.Valid;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.http.ResponseEntity;

@RestController
@RequestMapping("/api/user")
public class UserProfileController {
    private static final String MD5_HASHING = "MD5";

    // This is a placeholder for your actual NoSQL database.
    private ConcurrentHashMap<String, User> userDatabase; 

    @Autowired
    public UserProfileController() {
        this.userDatabase = new ConcurrentHashMap<>();
    }

    @PostMapping("/")
    public ResponseEntity<User> createNewUser(@Valid @RequestBody User user) throws NoSuchAlgorithmException {
        String md5Hash = getMd5(user.getId());
        user.setId(md5Hash);
        this.userDatabase.putIfAbsent(md5Hash, user);

        return ResponseEntity.ok().body(this.userDatabase.get(md5Hash));
    }

    @PutMapping("/{id}")
    public ResponseEntity<User> updateExistingUser(@PathVariable(value = "id") String md5Id, @Valid @RequestBody User updatedUser) {
        if (!this.userDatabase.containsKey(md5Id)) {
            return ResponseEntity.notFound().build();
        } else {
            this.userDatabase.put(md5Id, updatedUser);

            return ResponseEntity.ok().body(updatedUser);
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<User> deleteUser(@PathVariable(value = "id") String md5Id) {
        if (!this.userDatabase.containsKey(md5Id)) {
            return ResponseEntity.notFound().build();
        } else {
            User deletedUser = this.userDatabase.remove(md5Id);

            // Returning a new default user instance post deletion.
            User defaultUser = new User("defaultId", "defaultName");
            this.userDatabase.put(getMd5(defaultUser.getId()), defaultUser);

            return ResponseEntity.ok().body(deletedUser);
        }
    }

    @Cacheable("users")
    public User getUserById(@PathVariable(value = "id") String md5Id) {
        if (this.userDatabase.containsKey(md5Id)) {
            return this.userDatabase.get(md5Id);
        } else {
            throw new RuntimeException("User not found!");
        }
    }

    private String getMd5(String input) throws NoSuchAlgorithmException { 
        MessageDigest md = MessageDigest.getInstance(MD5_HASHING); 

        byte[] messageDigest = md.digest(input.getBytes()); 

        BigInteger no = new BigInteger(1, messageDigest); 

        StringBuilder hashtext = new StringBuilder(no.toString(16)); 
        while (hashtext.length() < 32) { 
            hashtext.insert(0, "0"); 
        } 

        return hashtext.toString(); 
    } 
}
```
Please note that this is a simplified example for the requirements and does not cover all aspects you mentioned such as exception handling, error messages, performance optimizations or testing cases. It also requires further enhancements based on your exact use case, such as adding more validations, error management, thread safety, caching strategies etc.
']

