const app = express();
app.use(express.json());

app.get('/loadModule/:moduleId', async (req, res) => {
    const { moduleId } = req.params;

    // Check if module already loaded in cache
    if (cacheModules[moduleId]) {
        return res.send({ result: cacheModules[moduleId] });
    }

    try {
        const response = await axios.get(`http://external-api/modules/${moduleId}`);

        // Load module from the external API 
        let mod = new Function('exports', 'require', 'module', response.data + '\n//# sourceURL=module.js');
        let moduleExports = { exports: {} };
        mod(moduleExports, require, module);

        // Cache the module for future use
        cacheModules[moduleId] = moduleExports;

        res.send({ result: moduleExports });
    } catch (error) {
        console.log('Error loading module', error);
        return res.status(500).send({ error: 'Failed to load module' });
    }
});

