import java.util.*;
import java.util.concurrent.*;
import java.util.stream.IntStream;

class DisjointSet {
    private final int[] parent, rank;
    private final MetadataService metadataService;

    public DisjointSet(int n) {
        this.parent = new int[n];
        this.rank = new int[n];
        this.metadataService = MetadataService.getInstance(); // replace with real implementation

        IntStream.range(0, n).forEach(i -> {
            parent[i] = i;
            rank[i] = 0;
        });
    }

    public int find(int x) throws InterruptedException, ExecutionException {
        if (parent[x] != x) {
            Integer cachedParent = metadataService.getCachedParent(x);
            parent[x] = cachedParent == null ? find(parent[x]) : cachedParent;
        }

        return parent[x];
    }

    public void union(int x, int y) {
        x = find(x);
        y = find(y);

        if (rank[x] < rank[y]) 
            parent[x] = y;
        else if (rank[x] > rank[y]) 
            parent[y] = x;
        else {
            parent[y] = x;
            rank[x]++;
        }

        metadataService.updateParent(parent[x], x); // update cache for new parent
    }
}

class MetadataService {
    private static final MetadataService instance = new MetadataService(); 
    private final Map<Integer, Integer> cachedParents = new ConcurrentHashMap<>();

    public static MetadataService getInstance() { return instance; } // Singleton pattern

    public void updateParent(int parent, int child) {
        cachedParents.put(child, parent);
    }

    public Integer getCachedParent(int x) throws InterruptedException, ExecutionException {
        if (cachedParents.containsKey(x)) 
            return cachedParents.get(x); // simulate rate-limited service with cache

        // replace with actual network call to metadata service
        CompletableFuture<Integer> future = CompletableFuture.supplyAsync(() -> {
            try {
                Thread.sleep(1000); // simulate delay from external service
            } catch (InterruptedException e) {
                throw new RuntimeException("Thread interrupted", e);
            }

            return getParentFromService(x);
        });

        return future.get();
    }

    private Integer getParentFromService(int x) { // replace with actual network call
        Random rand = new Random(); 
        return rand.nextInt(x + 1);
    }
}
```

