        saveLastAttackTime();
    }

    void addAttack(AttackFunction attack) {
        std::lock_guard<std::mutex> guard(attacksMutex_);
        attacks_.push_back(attack);
    }

    bool executeRandomAttack() {
        if (isOnCooldown()) return false;

        try {
            std::uniform_int_distribution<int> distribution(0, attacks_.size()-1);
            int attackIndex = distribution(randomEngine_);

            std::lock_guard<std::mutex> guard(attacksMutex_);
            attacks_[attackIndex](); // execute attack
