            logError("An error occurred while executing an attack: " + std::string(e.what()));
            return false;
        }

        lastAttackTime_ = std::chrono::system_clock::now();
        saveLastAttackTime(); // save the time in case of a crash
        logInfo("Executed attack");
        return true;
    }

private:
    bool isOnCooldown() {
        auto now = std::chrono::system_clock::now();
        auto durationSinceLastAttack = 
            std::chrono::duration_cast<std::chrono::milliseconds>(now - lastAttackTime_);

        return (durationSinceLastAttack.count() < config_.cooldown);
    }

    void loadLastAttackTime() {
        std::ifstream file("last_attack_time");
        if (!file) return;

        // Load time from file
        std::lock_guard<std::mutex> guard(lastAttackMutex_);
        file >> lastAttackTime_; 
    }

    void saveLastAttackTime() {
        std::ofstream file("last_attack_time");

        // Save time to file
