['Here is a high-level outline of how you might implement such a system in Java using Spring Boot for dependency management and asynchronous processing:

```java
import org.apache.commons.io.FileUtils;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

import java.io.*;
import java.nio.file.Files;
import java.util.concurrent.CompletableFuture;

@Service
public class SystemCommandExecutor {
    private static final int RETRY_LIMIT = 3;

    @Async("threadPoolTaskExecutor")
    public CompletableFuture<String> execute(String command) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder(command.split(" "));

        File logFile = Files.createTempFile("log", ".txt").toFile();
        File errFile = Files.createTempFile("err", ".txt").toFile();

        pb.redirectOutput(ProcessBuilder.Redirect.appendTo(logFile));
        pb.redirectError(ProcessBuilder.Redirect.appendTo(errFile));

        Process process = pb.start();

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            for (int i = 1; i <= RETRY_LIMIT; i++) {
                // Retry logic here...
            }
        }

        String output = FileUtils.readFileToString(logFile, "UTF-8");
        logFile.delete();

        return CompletableFuture.completedFuture(output);
    }
}
```

And for the file deletion service:

