using Polly;
using System.Net.Http;

public class DataIngestionService
{
    private readonly ConcurrentQueue<byte[]> _queue = new ConcurrentQueue<byte[]>();
    private Thread _processorThread;

    public void Start()
    {
        _processorThread = new Thread(ProcessData);
        _processorThread.Start();
    }

    public void Enqueue(byte[] data)
    {
        // Validate the byte array before enqueuing it to the queue
        if (data == null || data.Length > 1024 * 1024 * 100 /* 100MB */)
            throw new ArgumentException("Invalid data");

        _queue.Enqueue(data);
    }

    private void ProcessData()
    {
        while (true) // Replace with condition to exit the loop
        {
            if (!_queue.TryDequeue(out var data))
            {
                Thread.Sleep(1000);  // Adjust sleep time as necessary
                continue;
            }

            using (var connection = new SqlConnection("Your Connection String"))
            {
                // Assuming the byte array represents a file, we save it to SQL Server as varbinary(max)
                // You may need more complex logic for different data formats

                // Use Polly policy to handle transient errors
                var retryPolicy = Policy.Handle<SqlException>().Retry();

                retryPolicy.Execute(() =>
                {
                    connection.Open();

                    using (var command = new SqlCommand("INSERT INTO YourTable VALUES(@data)", connection))
                    {
                        // We use the varbinary(max) SQL Server data type to store byte arrays
                        command.Parameters.AddWithValue("@data", data);

                        command.ExecuteNonQuery();
                    }
                });
            }
        }
    }
}
