['```csharp
using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class SecureLoadDataService
{
    private const int MaxRetries = 5;
    private static readonly HttpClient httpClient = new HttpClient();

    public async Task<T> SecureLoadData<T>(byte[] ciphertext, string encryptionKey, byte[] iv, string apiEndpoint)
    {
        for (int attempt = 0; attempt < MaxRetries; attempt++)
        {
            try
            {
                var payload = new 
                {
                    Ciphertext = Convert.ToBase64String(ciphertext),
                    EncryptionKey = encryptionKey,
                    IV = Convert.ToBase64String(iv)
                };

                string jsonPayload = JsonConvert.SerializeObject(payload);
                var content = new StringContent(jsonPayload, Encoding.UTF8, "application/json");

                HttpResponseMessage response = await httpClient.PostAsync(apiEndpoint, content);
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception("HTTP request failed.");
                }

                string jsonResponse = await response.Content.ReadAsStringAsync();
                T decryptedObject = JsonConvert.DeserializeObject<T>(jsonResponse);

                return decryptedObject;
            }
            catch (Exception ex)
            {
                if (attempt == MaxRetries - 1)
                {
                    // Log the final failure.
                    Console.WriteLine($"{DateTime.Now} : Loading failed: {ex.Message}");
                    return default;
                }

                int delay = (int)Math.Pow(2, attempt);  // Exponential backoff.
                await Task.Delay(delay * 1000);  // Convert seconds to milliseconds.
            }
        }

        return default;
    }
}
```
