['Here is a simplified solution to your problem in Java using Google GSON library for serialization/deserialization. This code won't cover all aspects of your request like high concurrency, detailed error handling but it gives you the basic idea on how to handle serialized transaction records and produce a list of transaction objects:

```java
import com.google.gson.*;
import java.io.*;
import java.util.*;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;

public class TransactionService {

    private final Gson gson = new GsonBuilder().create();

    public List<Transaction> deserializeTransactions(InputStream in) throws IOException{
        BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
        JsonArray jsonArr;
        try {
            // read the stream into a string
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }

            // parse the string into a JsonArray
            jsonArr = gson.fromJson(sb.toString(), JsonArray.class);
        } catch (JsonSyntaxException e) {
            throw new IOException("Failed to deserialize transaction records: " + e.getMessage());
        }

        // convert the JsonElements in the array into Transaction objects
        List<Transaction> transactions = new ArrayList<>();
        for (JsonElement jsonElem : jsonArr) {
            try {
                Transaction txn = gson.fromJson(jsonElem, Transaction.class);
                transactions.add(txn);
            } catch (JsonSyntaxException e) {
                System.out.println("Failed to deserialize transaction record: " + jsonElem.toString() + ". Reason: " + e.getMessage());
            }
        }

        return transactions;
    }

    public static class Transaction implements Serializable {
        private String id;
        private double amount;

        // getters and setters...
    }
}
```
