['Below is a simplified implementation of what you're asking for. It omits some specific details due to their complexity (like actual logging, error handling, thread safety etc.) but provides a high-level overview of how one might approach such a problem using Python and its ecosystem of libraries. 

```python
import json
from typing import Dict, Any
from jsonschema import validate, ValidationError
from collections import defaultdict
import logging

logging.basicConfig(filename='json_parser.log', level=logging.INFO)

class JsonData:
    def __init__(self):
        self.registry = defaultdict(list)
        self.version_history = {}

    def register_factory(self, factory, schema, version):
        if version in self.version_history and \
                self.version_history[version] != factory:
            logging.info('Deprecating old version of the function')

        self.registry[schema].append((factory, version))
        self.version_history[version] = factory

    def remove_factory(self, factory):
        for key in list(self.registry.keys()):  # iterate over keys
            if any(fct == factory for fct, _ in self.registry[key]):
                del self.registry[key]

    def get_factory(self, schema, version=None):
        factories = self.registry.get(schema)

        if not factories:
            return None

        if version is not None:
            for fct, ver in reversed(factories):  # reverse iterate over versions
                if ver <= version:
                    return fct

        return self.version_history[self.registry[schema][0][1]]

    def instantiate(self, json_str: str) -> Any:
        data = json.loads(json_str)

        try:
            validate(data, schema={"type" : "object"})  # replace with your actual schema
        except ValidationError as ve:
            logging.error('Invalid JSON format')
            raise ValueError('Invalid JSON format') from ve

        factory = self.get_factory({'type': 'object'}, data['version'])  # replace with your actual version handling

        if not factory:
            logging.info('No matching factory found for schema, using default')
            return data  # use a default or error here as needed

        try:
            obj = factory(data)
        except Exception as ex:
            logging.error('Factory function failed with exception', exc_info=ex)
            raise RuntimeError('Failed to instantiate object') from ex

        return obj
``` 
Please note that this is a simplified version and not intended for production usage. In real-life scenario, you would need to handle much more complex scenarios including thread safety, performance optimization, integration with external configuration management system, error handling, logging etc. It also lacks tests.
