    json_object *token, *type, *expiry, *refresh;

    json_object_object_get_ex(jobj, "access_token", &token);
    json_object_object_get_ex(jobj, "token_type", &type);
    json_object_object_get_ex(jobj, "expires_in", &expiry);

    if(!json_object_is_type(token, json_type_string) ||
       !json_object_is_type(type, json_type_string) || 
       strcmp(json_object_get_string(type), "Bearer") ||
       !json_object_get_int(expiry) > 0){
        return 0;
    }

    // If the refresh token is optional, check it only if it exists.
    if(!json_object_object_get_ex(jobj, "refresh_token", &refresh)){
        if (!json_object_is_type(refresh, json_type_string)) {
            return 0;
        }
    }

    return 1;
}

void curlErrorCheck(CURLcode result, char* message){
    if (result != CURLE_OK) {
        fprintf(stderr, "%s\n", message);
    }
}

int main() {
    // Initialize libcurl 
    CURL *curl = curl_easy_init();
    if(!curl) {
       return 1;
    }

    struct stat st = {0};
    char* targetDirectory = "/path/to/target";
    if (stat(targetDirectory, &st) == -1) {
        mkdir(targetDirectory, 0700);
    }

    // Initialize and start threads for concurrent processing of log entries.
    pthread_t threads[NUM_THREADS];
    thread_data_t threadData[NUM_THREADS];

    for(int i = 0; i < NUM_THREADS; ++i) {
        // Initialize thread data with filenames. 
        pthread_create(&threads[i], NULL, processLogEntry, (void *)&threadData[i]);
    }

    for(int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);  // wait for all threads to finish
    }

    // Clean up libcurl resources.
    curl_easy_cleanup(curl);

    return 0;
}
```
This is a basic skeleton implementation of the program. In real-world scenarios, you would need to add error handling for different failure conditions and handle more intricate log file parsing based on your specific requirements. The JSON payload validation can be further fine-tuned according to the specific OAuth2 specification. Also, you might want to use a more robust logging system (like syslog) instead of printing directly to stderr.
']

