void* asyncAddToDataStore(void *args) {
    struct Arguments* arguments = (struct Arguments*) args;
    DataNode* node = arguments->dataNode;

    // retry mechanism for asynchronous operations with configurable timeout
    int attempts = 0;
    while(!dataStoreAvailability && attempts < MAX_RETRY) {
        validateDataStore();  // check if data store is available and connect if not already done
        ++attempts;
        sleep(arguments->timeout);
    }

    // perform the add operation on the data store here
