#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Define a struct for your data 
typedef struct {
    char *data;
    pthread_mutex_t lock;
} string_metadata_t;

string_metadata_t* new_string(const char* str) {
    string_metadata_t* metadata = malloc(sizeof(string_metadata_t));
    if (pthread_mutex_init(&metadata->lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        free(metadata);
        return NULL;
    }

    size_t len = strlen(str);
    metadata->data = malloc(len + 1); // +1 for null terminator
    strcpy(metadata->data, str);

    return metadata;
}

void delete_string(string_metadata_t* metadata) {
    if (metadata == NULL) 
        return;

    pthread_mutex_destroy(&metadata->lock);
    free(metadata->data);
    free(metadata);
}

int add_suffix(string_metadata_t* metadata, const char* suffix) {
    if (metadata == NULL || suffix == NULL) 
        return -1;

    pthread_mutex_lock(&metadata->lock); // Lock before modifying the string

    size_t len = strlen(suffix);
    size_t old_len = strlen(metadata->data);

    metadata->data = realloc(metadata->data, old_len + len + 1); // +1 for null terminator
    if (metadata->data == NULL) {
        pthread_mutex_unlock(&metadata->lock); // Unlock before returning in case of error
        return -1;
    }

    strcpy(metadata->data + old_len, suffix);

    pthread_mutex_unlock(&metadata->lock); // Unlock after modifying the string

    return 0;
}
```
This is a basic example of how to use mutexes for thread safety in C. The `add_suffix` function locks the mutex before it modifies the shared data, and unlocks it after it finishes modifying the data. This ensures that other threads can't access the data until the current operation completes.

