    LLVMInitializeNativeTarget("".to_string());

    let opt = Opt::from_args();

    let mut parser = grammar::ProgramParser::new();
    match opt.input {
        Some(ref file) => {
            let mut buf = String::new();
            std::fs::File::open(&file)?.read_to_string(&mut buf)?;
            println_ir(parser.parse(buf).unwrap().0);
