```cpp
#include <iostream>
#include <random>
#include <thread>
#include <mutex>
#include <vector>
#include <curl/curl.h>

std::mutex mtx;           // Mutex for thread safety
CURL *curl;                // Curl handle
struct curl_slist *chunk = NULL;
CURLcode res;
std::string readBuffer;

// Function to fetch data from third-party API
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Function to fetch random number from external API and handle errors.
std::string getRandomNumberFromAPI() {
    mtx.lock(); // Lock mutex before making the request.

    readBuffer.clear();  // Clear buffer before each request.
    res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
        std::cerr << "Error occurred while fetching random number from API: " << curl_easy_strerror(res) << std::endl;
    } else {
        std::cout << readBuffer << std::endl;  // Print the received data.
    }

    mtx.unlock(); // Unlock mutex after finishing the request.
}

// Function to generate random number in multi-threaded environment
std::vector<std::thread> threads;
void runRandomNumberGenerator() {
    for (int i = 0; i < 10; ++i) {
        threads.push_back(std::thread(getRandomNumberFromAPI)); // Create and start the thread.
    }

    for (auto &th : threads) {
        th.join(); // Wait for all threads to finish.
    }
}

int main() {
    curl = curl_easy_init();   // Initialize curl handle.

    if(curl) {
        chunk = curl_slist_append(chunk, "Accept: application/json");  // Set request headers.
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, chunk);
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com");   // Set API URL.

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);  // Set callback function.
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);       // Pass buffer to store response into.

        runRandomNumberGenerator();  // Run the threaded random number generator.

        curl_easy_cleanup(curl);     // Clean up curl handle.
    }

    return 0;
}
```
