In the following code, `ConfigurationService` is responsible for fetching XML configuration files from an external source (in this case, it's just returning dummy data). The configuration data is parsed into a dictionary structure and stored in memory cache using Microsoft's `IMemoryCache` interface. Cache invalidation is done via `MemoryCacheEntryOptions`.

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;
using Microsoft.Extensions.Caching.Memory;

public class ConfigurationService 
{
    private readonly IMemoryCache _cache;
    private static string CacheKey = "config";

    public ConfigurationService(IMemoryCache cache)
    {
        _cache = cache;
    }

    public Dictionary<string, string> GetConfiguration()
    {
        // Try to get the configuration from the cache.
        if (!_cache.TryGetValue(CacheKey, out Dictionary<string, string> config))
        {
            // Key not in cache - fetch it and add it.
            config = FetchConfiguration();

            var cacheEntryOptions = new MemoryCacheEntryOptions()
                .SetAbsoluteExpiration(TimeSpan.FromMinutes(5)); // Cache will expire after 5 minutes.

            _cache.Set(CacheKey, config, cacheEntryOptions);
        }

