['Building such a comprehensive Python library requires extensive code. Here's a simplified outline to help you get started:

```python
import json
import boto3
from botocore.exceptions import BotoCoreError, NoCredentialsError
from threading import Lock
from collections import defaultdict

class ConfigSyncer(object):
    def __init__(self, bucket_name, region=None):
        self._s3 = boto3.client('s3', region_name=region)
        self._bucket_name = bucket_name
        self._data = defaultdict(lambda: {'version': 0})
        self._lock = Lock()

    def _fetch_remote_config(self, key):
        try:
            response = self._s3.get_object(Bucket=self._bucket_name, Key=key)
            data = json.loads(response['Body'].read().decode('utf-8'))
            return data
        except NoCredentialsError as e:
            print("No AWS credentials found")
            raise e
        except BotoCoreError as e:
            print(f"AWS error occurred: {e}")
            raise e

    def _update_remote_config(self, key, data):
        try:
            self._s3.put_object(Bucket=self._bucket_name, Key=key, Body=json.dumps(data))
        except NoCredentialsError as e:
            print("No AWS credentials found")
            raise e
        except BotoCoreError as e:
            print(f"AWS error occurred: {e}")
            raise e

    def synchronize(self, key):
        with self._lock:
            remote_data = self._fetch_remote_config(key)
            local_version = self._data[key]['version']
            remote_version = remote_data.get('version', 0)

            if remote_version > local_version:
                self._data[key] = remote_data
                print(f"Updated {key} from version {local_version} to {remote_version}")
            elif local_version > remote_version:
                conflict_strategy = self.resolve_conflict(self._data[key], remote_data)

                if conflict_strategy == 'LOCAL':
                    print(f"Conflict resolved by keeping local data for {key}")
                elif conflict_strategy == 'REMOTE':
                    self._update_remote_config(key, self._data[key])
                    print(f"Conflict resolved by updating remote data for {key}")

            else:
                print(f"No need to synchronize {key}, versions are equal ({local_version})")
```
This is a simplified version of your library and it will be much larger. Also, handling failures, logging, error recovery, concurrent processing for efficient scaling with an expanding service ecosystem etc. can get very complex based on the specific requirements.
