['Here is a basic implementation of your specifications in Python using BeautifulSoup for HTML parsing and networkx for knowledge graph construction:
```python
import requests
from bs4 import BeautifulSoup
import networkx as nx
import time
from concurrent.futures import ThreadPoolExecutor
import logging

logging.basicConfig(filename='web_scraper.log', level=logging.INFO)

class WebScraper:
    def __init__(self, urls):
        self.urls = urls
        self.cache = {}
        self.graph = nx.Graph()

    def scrape(self, url):
        if url not in self.cache or time.time() - self.cache[url]['timestamp'] > 86400:  # If data is older than 24 hours or not cached
            try:
                response = requests.get(url)
                html_content = response.text

                soup = BeautifulSoup(html_content, 'html.parser')
                tags = [tag.name for tag in soup.find_all()]
                frequencies = {i: tags.count(i) for i in tags}

                self.cache[url] = {'timestamp': time.time(), 'data': frequencies}  # Update cache
            except requests.exceptions.RequestException as e:  
                logging.error("Failed to scrape %s: %s", url, str(e))

    def update_graph(self):
        for url in self.urls:
            if url in self.cache and 'data' in self.cache[url]:  # If data is cached
                tags = self.cache[url]['data']

                for tag, frequency in tags.items():
                    self.graph.add_node(tag)

                    if self.graph.degree(tag) > 0:  # If node already exists (has edges to other nodes)
                        current_frequency = self.graph.nodes[tag]['frequency']
                        self.graph.nodes[tag]['frequency'] = max(current_frequency, frequency)  # Update with maximum observed frequency
                    else:
                        self.graph.nodes[tag]['frequency'] = frequency

    def run(self):
        with ThreadPoolExecutor(max_workers=100) as executor:  
            for _ in range(24):  # Run for a day
                executor.map(self.scrape, self.urls)

                time.sleep(3600)  # Sleep for an hour before starting the next cycle

        self.update_graph()
```
