```javascript
class AssembleAndInsertScripts {
    constructor(config) {
        this.scripts = config;
        this.loadedScripts = new Set(); // to keep track of loaded scripts
    }

    loadScript(scriptUrl) {
        return new Promise((resolve, reject) => {
            const scriptEl = document.createElement('script');
            scriptEl.src = scriptUrl;
            scriptEl.onload = resolve;
            scriptEl.onerror = reject;
            document.body.appendChild(scriptEl);
        });
    }

    loadScripts() {
        return Promise.allSettled(this.scripts.map(({ url }) => {
            if (!this.loadedScripts.has(url)) { // avoid loading same script twice
                this.loadedScripts.add(url);
                return this.loadScript(url);
            } else {
                return Promise.resolve(); // ignore loaded scripts
            }
        }));
    }
}
```
