const express = require('express');
const axios = require('axios');
const redis = require('redis');
const {promisify} = require('util');
const pm2 = require('pm2');

// Create Redis client and enable async operations
const client = redis.createClient();
client.get = promisify(client.get);
client.set = promisify(client.set);

// Initialize express app
const app = express();
app.use(express.json());

// Middleware for handling API errors
function asyncMiddleware(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// Get data from external API and cache it
app.get('/api/data', asyncMiddleware(async (req, res) => {
  const cachedData = await client.get('external_data');

  if (cachedData) {
    return res.json(JSON.parse(cachedData));
  } else {
    const response = await axios.get('https://api.example.com/data');
    // You need to validate the data here, for example:
    if (!response || !response.data) throw new Error("Invalid or corrupted data!");

    client.set('external_data', JSON.stringify(response.data));
    res.json(response.data);
  }
}));

// Start the server and handle process errors
pm2.start({
  script: 'app.js',
  exec_mode: 'cluster',
  instances: -1, // Let PM2 decide how many worker processes to start based on available CPU cores
}, (err) => {
  if(err){
    console.error("Error starting the server", err);
    process.exit(1);
  } else {
    console.log('Server is running');
  }
});
```
