fn measure_compilation_and_size() -> Result<(), ()> {
    let pre = get_resident_set_size();
    let start = time::Instant::now();

    let _icehook = SyncLazy::new(|| {
        catch_with_exit_code(|| unsafe {
            early_error("Compilation failed")
