    private readonly AuthApiClient _authApiClient;
    private readonly UserManagerClient _userManagerClient;
    private readonly ThirdPartyIdentityProviderClient _thirdPartyIdentityProviderClient;

    public AuthenticationService(IDistributedCache cache, 
                                 AuthApiClient authApiClient, 
                                 UserManagerClient userManagerClient,
                                 ThirdPartyIdentityProviderClient thirdPartyIdentityProviderClient)
    {
        _cache = cache;
        _authApiClient = authApiClient;
        _userManagerClient = userManagerClient;
        _thirdPartyIdentityProviderClient = thirdPartyIdentityProviderClient;
    }

    public async Task<string> GenerateHash(User user, CancellationToken cancellationToken)
    {
        string hashKey = $"hash_{user.Id}";

        byte[] cachedHash = await _cache.GetAsync(hashKey);

        if (cachedHash != null) 
            return Convert.ToBase64String(cachedHash);

        var userData = await _authApiClient.GetUserDataAsync(user, cancellationToken);
        var hashValue = ComputeSHA256(userData.ToString()); // Implement your own logic to compute the SHA-256 hash

        await _cache.SetAsync(hashKey, hashValue);

        return Convert.ToBase64String(hashValue);
    }

    private byte[] ComputeSHA256(string value) 
    {
        using (var sha = SHA256.Create())
            return sha.ComputeHash(Encoding.UTF8.GetBytes(value));
    }
}
```
