typedef void (*filter_func)(unsigned char *data, int width, int height);

int main() {
    void *handle = dlopen("./my_filters.so", RTLD_LAZY);
    if (!handle) {
        printf("%s\n", dlerror());
        return 1;
    }

    filter_func filter = (filter_func)dlsym(handle, "edge_detection");
    char *error = dlerror();
    if (error != NULL) {
        printf("%s\n", error);
        return 1;
    }

    // Assume you have an image loaded into memory
    unsigned char *data = ...;
    int width = ..., height = ...;

    filter(data, width, height);

    dlclose(handle);
    return 0;
}
```

The `my_filters.so` is a shared object file (DSO) that contains the `edge_detection` function. You could build it with something like:

