```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
// Assume a dns_api class and its methods like query, getApiProviderRateLimit etc.

class DNSResolver {
    std::vector<dns_api*> apis; // List of available APIs
    std::mutex mtx; 

public:
    void addAPI(dns_api* api) {
        apis.push_back(api);
    }

    dns_query resolveDNS(std::string domain, std::string location){
        std::vector<std::thread> threads; 
        mtx.lock(); // Lock to ensure no further addition of API's

        for (auto api : apis) {
            if(api->getApiProviderLocation() == location){ // If the location matches with the provider, use it
                threads.push_back(std::thread([&](){ dns_query result = api->query(domain);  }));
            }else{
                threads.push_back(std::thread([&](){ dns_query result = api->query(domain); })); // Else, use any API
            }
        }

        mtx.unlock(); // Unlock as we will add more APIs soon if needed

        for (auto &th : threads) { 
           th.join(); // Wait for all threads to complete
        } 
    }
};
```
In a real-world scenario, caching and machine learning aspects would be added on top of this design as well. This also does not take into account DDoS attacks or other potential issues that might arise in production systems. For these, you may want to look into rate limiting algorithms, using cloud-based solutions for managing infrastructure, etc.
