```javascript
const crypto = require('crypto');
const childProcess = require('child_process');
const fs = require('fs');
const http = require('http');
const logger = console; // Replace with actual logger
let cache = {}; // Local caching strategy to prevent data loss
let hashAlgorithm = 'sha256'; // Default hashing algorithm

function fetchMetadata(file) {
    return new Promise((resolve, reject) => {
        http.get({ host: 'api.host.com', path: '/metadata' + file }, (resp) => {
            let data = '';

            resp.on('data', (chunk) => {
                data += chunk;
            });

            resp.on('end', () => {
                resolve(JSON.parse(data));
            });
        }).on("error", (err) => {
            reject(err);
        });
    });
}

function computeHash(file, algorithm = hashAlgorithm) {
    return new Promise((resolve, reject) => {
        const shasum = crypto.createHash(algorithm);
        const stream = fs.createReadStream(file);

        stream.on('data', function(data) {
            shasum.update(data);
        });

        stream.on('end', function() {
            resolve(shasum.digest('hex'));
        });
    });
}

function safeExecShellCommand(command, args) {
    return new Promise((resolve, reject) => {
        const commandStr = [command].concat(args).join(' ');
        childProcess.exec(commandStr, (error, stdout, stderr) => {
            if (error) {
                logger.error(`Error executing shell command: ${commandStr}`);
                reject(error);
            } else {
                resolve({stdout, stderr});
            }
        });
    });
}

// Testing
safeExecShellCommand('ls', ['-lh', '/usr']);
```
This code provides a high level design and demonstrates the key components. In reality, you would need to integrate these concepts into a larger application with error handling, testing, resilience strategies etc as well as additional services for caching, metadata fetching and shell command execution. The actual implementation will vary based on specific requirements, constraints, available infrastructure and environment.
