using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Polly;
using StackExchange.Redis;

namespace BatchService.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class BatchController : ControllerBase
    {
        private readonly IConfiguration _config;
        private readonly ConnectionMultiplexer _redisConnection;
        private readonly ILogger<BatchController> _logger;

        public BatchController(IConfiguration config, ILogger<BatchController> logger)
        {
            _config = config;
            _redisConnection = ConnectionMultiplexer.Connect(_config["Redis:ConnectionString"]);
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody] BatchRequest batch)
        {
            if (!ModelState.IsValid || !batch.IsValid)
                return BadRequest();

            var db = _redisConnection.GetDatabase();
            var rateLimitingPolicy = Policy.Handle<RedisTimeoutException>()
                                       .RetryAsync(5);

            await rateLimitingPolicy.ExecuteAsync(() =>
            {
                // Process requests here, potentially offloading tasks to a message broker for asynchronous processing
                var taskCompletionSources = new List<TaskCompletionSource<bool>>();

                foreach (var request in batch.Requests)
                {
                    var taskCompletionSource = new TaskCompletionSource<bool>();

                    // This could be a direct call to another microservice or an asynchronous message sent to a queue for processing later on.
                    db.StringSetAsync(request.Key, request.Value);

                    taskCompletionSources.Add(taskCompletionSource);
                }

                return Task.WhenAll(taskCompletionSources.Select(tcs => tcs.Task));
            });

            // Return status here
        }
    }
}
