#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    pthread_mutex_t mutex;
    void *data;
} Resource;

Resource* createResource(void) {
    Resource *resource = malloc(sizeof(*resource));
    if (resource != NULL) {
        pthread_mutex_init(&resource->mutex, NULL);
        resource->data = NULL;
    }
    return resource;
}

void destroyResource(Resource *resource) {
    if (resource != NULL) {
        pthread_mutex_destroy(&resource->mutex);
        free(resource->data);
        free(resource);
    }
}

void accessResource(Resource *resource, void (*process)(void*)) {
    if (resource == NULL || process == NULL) return;

    pthread_mutex_lock(&resource->mutex);

    process(resource->data);

    pthread_mutex_unlock(&resource->mutex);
}
```

In the above, I've implemented a simple locking mechanism with `pthread_mutex` which ensures thread safety. The library operates on resources that have a mutex and some data to protect. The function `accessResource()` is then used to manage access to this resource safely.

