```c
#include <pthread.h>
// Other necessary includes go here

typedef struct Record {
    int* key;
    long* offset;
    pthread_mutex_t reference_counter;
} Record;

Record* records = NULL; // Global pointer to array of Records
pthread_mutex_t lock;  // Lock for thread-safety
int count = 0;         // Number of elements in the Record array

// Allocate memory and initialize Record array
void initRecords(size) {
    records = (Record*)malloc(size * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Error allocating memory for Records\n");
        exit(1);
    }
}

// Thread-safe method to update a Record
void updateRecord(int index, int newKey, long newOffset) {
    pthread_mutex_lock(&lock); // Lock the mutex before modifying records
    if (records[index].key != NULL || records[index].offset != NULL) {
        fprintf(stderr, "Error: attempting to modify non-empty Record\n");
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning
        return;
    }
    // Allocate memory and set new values for the Record at index
    records[index].key = (int*)malloc(sizeof(int));
    *records[index].key = newKey;
    records[index].offset = (long*)malloc(sizeof(long));
    *records[index].offset = newOffset;

    pthread_mutex_unlock(&lock); // Unlock the mutex after modifying records
}
```
This is a high-level and simplified overview of how you might approach each part of your task. Developing such a system would require significant effort, careful design, testing, and potentially ongoing maintenance. Also, please note that JavaScript alone cannot directly interact with external databases or other systems like these. It typically relies on server-side technologies for that kind of integration.
