```java
import org.springframework.stereotype.Service;

@Service
public class TaskManager {
    // Define services
    private CloudStorageProvider cloudStorageProvider;
    private AnalyticsApi analyticsApi;

    // Configuration properties
    @Value("${taskmanager.concurrency:5}")
    private int concurrencyLimit;

    @Value("${taskmanager.frequency:1000}")
    private long frequency;

    private ScheduledExecutorService executorService;
    private AtomicLong taskCounter = new AtomicLong();

    // Configure scheduling properties
    public void setFrequency(long frequency) {
        this.frequency = frequency;
        rescheduleTasks();
    }

    public void setConcurrencyLimit(int concurrencyLimit) {
        this.concurrencyLimit = concurrencyLimit;
        rescheduleTasks();
    }

    // Dynamic configuration properties
    @Value("${taskmanager.cloudstorageprovider}")
    public void setCloudStorageProviderEndpoint(String endpoint){
      cloudStorageProvider.setEndpoint(endpoint);
      cloudStorageProvider.updateConfiguration();
    }

    // Start task scheduler with initial configuration
    @PostConstruct
    public void init() {
        executorService = Executors.newScheduledThreadPool(concurrencyLimit);
        scheduleTasks();
    }

    private void rescheduleTasks(){
      executorService.shutdownNow(); // Cancel currently scheduled tasks
      scheduleTasks(); // Schedule new tasks with updated configuration
    }

    // Schedule tasks
    private void scheduleTasks() {
        for (int i = 0; i < concurrencyLimit; i++) {
            executorService.scheduleAtFixedRate(this::runTask, 0, frequency, TimeUnit.MILLISECONDS);
        }
    }

    // Task execution logic
    private void runTask() {
      long taskId = taskCounter.incrementAndGet();

      try {
          String dataSet = cloudStorageProvider.fetchData(taskId);

          processDataSet(dataSet);

          analyticsApi.submitResults(results);

