['Your request is a complex task that requires many components and layers of the application stack. Writing all of this out in a single response would be impossible due to length considerations. 

Here's a very simplified example of how you could start building an IoT management system using C++, assuming we are talking about some kind of MQTT-based messaging system:

```cpp
#include <iostream>
#include <cstdlib>
#include <string>
#include "paho-mqtt/MQTTClient.h"

#define ADDRESS     "tcp://localhost:1883" // change this to your broker address
#define CLIENTID    "ExampleClientPub"
#define TOPIC       "hello"
#define PAYLOAD     "Hello World!"
#define QOS         1
#define TIMEOUT     10000L

using namespace std;

int main(int argc, char* argv[]) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&client, ADDRESS, CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        cout << "Failed to connect, return code " << rc << endl;
        exit(-1);
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    pubmsg.payload = (void*) PAYLOAD;
    pubmsg.payloadlen = strlen(PAYLOAD);
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    MQTTClient_publishMessage(client, TOPIC, &pubmsg, &token);
    cout << "Waiting for up to " << (int)(TIMEOUT/1000) << " seconds for publication of " << PAYLOAD 
        << " \non topic " << TOPIC << " for client with ClientID: " << CLIENTID << endl;

    rc = MQTTClient_waitForCompletion(client, token, TIMEOUT);
    cout << "Message with delivery token " << (int)token << " delivered." << endl;

    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);

    return rc;
}
```

This is a simple C++ application that publishes a message to an MQTT broker. The full system you're describing would be much larger and involve many more components, including but not limited to:
