Here's a simplified example of how you might implement some parts of this service using Rocket (a web framework for Rust), Diesel (an ORM for Rust), Tokio for asynchronous I/O, and other crates. 

```rust
#[macro_use]
extern crate diesel;
extern crate dotenv;
extern crate rocket;
#[macro_use]
extern crate serde_json;
extern crate std;

use rocket::http::Status;
use rocket::request::FromRequest;
use rocket::response::content::Json;
use rocket::{Build, Rocket};
use dotenv::dotenv;
use diesel::prelude::*;
use std::fs::File;
use std::io::Read;
use serde_derive::Deserialize;
use std::collections::HashSet;
use futures::stream::StreamExt;

table![employees, id -> Integer, name -> Text, city -> Text, address -> Text];

#[derive(Queryable, Deserialize)]
struct Employee {
    id: i32,
    name: String,
    city: String,
    address: String,
}

pub fn create_api() -> Rocket<Build> {
    dotenv().ok();
    let database_url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");

    rocket::ignite()
        .manage(diesel::r2d2::Pool::builder(database_url)
            .build().unwrap())
}

#[derive(FromForm)]
pub struct Ids {
    ids: Vec<i32>,
}

impl FromRequest for Ids {
    type Error = &'static str;

    fn from_request(request: &rocket::Request) -> request::Outcome<Self, Self::Error> {
        match Ids::from_data(request.into_inner()).fuse() {
            Outcome::Success(_ids) => Outcome::Failure((Status::BadRequest, "No form data")),
            outcome => outcome,
        }
    }
}

#[get("/employees?<ids>")]
fn get_employees(pool: &diesel::r2d2::Pool, ids: Ids) -> Json<HashSet<Employee>> {
    use employees::table;

    let connection = pool.get().unwrap();
    let mut results = HashSet::new();

    for id in ids.0 {
        if let Some(employee) = employees::table.find_by_id(&*connection, id).optional() {
            results.insert(employee);
        }
    }

    Json(results)
}
```

