            if (!ec || ec == asio::error::eof) break;

            // backoff and retry after random delay up to 1 second
            std::cerr << "Retrying read operation..." << std::endl;
            this_thread::sleep_for(std::chrono::milliseconds(distribution(generator)));
        } catch (const std::exception& e) {
            // handle exceptions and retry
            std::cerr << "Exception: " << e.what() << "\n";
            this_thread::sleep_for(std::chrono::milliseconds(distribution(generator)));
        }
    }

    ss << &b;

