['Creating a full C library that meets all these criteria is complex, requires extensive knowledge of libraries such as libcurl for HTTP requests, json-c or cJSON for JSON parsing, and glib's GAsyncQueue for asynchronous processing. Below is an example of how you can start coding this in C.

Please note this is a simplified example without the full functionality described above:

```c
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>

struct string {
  char *ptr;
  size_t len;
};

void init_string(struct string *s) {
  s->len = 0;
  s->ptr = malloc(s->len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);

  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }

  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

void get_json_data(char *url) {
  CURL *curl;
  CURLcode res;

  curl = curl_easy_init();
  if(curl) {
    struct string s;
    init_string(&s);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

    res = curl_easy_perform(curl);

    if(res != CURLE_OK)
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

    long response_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

    if(response_code == 200) {
      json_object *jobj = json_tokener_parse(s.ptr);

      // Process JSON data...
      printf("%s\n", json_object_to_json_string(jobj));
      json_object_put(jobj);
    }

    free(s.ptr);
    curl_easy_cleanup(curl);
  }
}
```

This example fetches a JSON response from a URL and parses it into a C object, but does not implement OAuth2 or any of the other features you mentioned. It also doesn't handle error cases in an efficient way.
']

