```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int key;
    long offset_value;
} record;

// For demonstration purposes, these are made global 
record* pool; // Memory pool to hold records
atomic_int index = 0; // Current index in the pool
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safety

// Function to handle allocation and initialization of record structures
record* allocate_initialize(int key, long offset_value) {
    pthread_mutex_lock(&lock); // Locking the critical section

    if (index >= pool_size) { // Check for overflow
        pthread_mutex_unlock(&lock); 
        return NULL;
    }

    record* new_record = &pool[atomic_fetch_add(&index, 1)]; // Allocate memory and initialize it
    new_record->key = key;
    new_record->offset_value = offset_value;

    pthread_mutex_unlock(&lock); // Unlocking the critical section

    return new_record;
}
```

This is a very simplified example. It does not include error handling, database/message queue service integrations, garbage collection for resource exhaustion prevention etc. As mentioned earlier, it's highly recommended to have an experienced team for this kind of task. For such complex tasks, design patterns like Producer-Consumer pattern or Observer Pattern can be used.
