#include <php.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char* id;
    // other status fields...
} NetworkEntityStatusUpdate;

// A simple linked list to manage the updates, with a lock for thread safety
static pthread_mutex_t updateListLock = PTHREAD_MUTEX_INITIALIZER;
static struct UpdateNode {
    NetworkEntityStatusUpdate update;
    struct UpdateNode* next;
} *updateListHead;

// Add an update to the list, thread-safely
void addUpdate(NetworkEntityStatusUpdate update) {
    pthread_mutex_lock(&updateListLock);

    // Create new node and set data
    struct UpdateNode* newNode = malloc(sizeof(struct UpdateNode));
    newNode->update = update;
    newNode->next = NULL;

    if (updateListHead == NULL) {
        // If list is empty, this node becomes the head
        updateListHead = newNode;
    } else {
        // Find last node and append our new node
        struct UpdateNode* currentNode = updateListHead;
        while(currentNode->next != NULL) {
            currentNode = currentNode->next;
        }

        currentNode->next = newNode;
    }

    pthread_mutex_unlock(&updateListLock);
}
``` 

