typedef struct Item {
    int id;
    char* status;
    struct Item** dependencies;
    size_t dependencyCount;
    pthread_mutex_t lock;
} Item;

// Global collection of items and associated mutex for thread safety.
Item** collection;
size_t collectionSize;
pthread_mutex_t collectionLock = PTHREAD_MUTEX_INITIALIZER;

void addDependency(Item* item, Item* dependency) {
    pthread_mutex_lock(&item->lock);
    item->dependencies[item->dependencyCount++] = dependency;
    pthread_mutex_unlock(&item->lock);
}

void* addItem(void* arg) {
    Item* newItem = (Item*)arg;

    pthread_mutex_lock(&collectionLock);
    collection[collectionSize++] = newItem;
    pthread_mutex_unlock(&collectionLock);

    return NULL;
}

char* itemToJson(const Item* item) {
    json_t *json = json_object();
    json_object_set_new(json, "id", json_integer(item->id));
