#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct LogEntry {
    time_t timestamp;
    char level[5];
    char message[256];
    struct LogEntry *next;
} LogEntry;

LogEntry *head = NULL;
LogEntry *tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log(char level[5], char message[256]) {
    pthread_mutex_lock(&lock);

    LogEntry *newEntry = (LogEntry*) malloc(sizeof(LogEntry));
    newEntry->timestamp = time(NULL);
    strcpy(newEntry->level, level);
    strcpy(newEntry->message, message);
    newEntry->next = NULL;

    if (head == NULL) {
        head = tail = newEntry;
    } else {
        tail->next = newEntry;
        tail = newEntry;
    }

    pthread_mutex_unlock(&lock);
}

void sendToExternalService() {
    // Implement the logic to periodically upload logs to an external service.
    // This could be done using a separate thread or some other method, depending on the requirements of your specific use case.

    pthread_mutex_lock(&lock);

    LogEntry *current = head;
    while (current != NULL) {
        char logString[512];
        sprintf(logString, "%ld [%s] %s", current->timestamp, current->level, current->message);

        // Implement sending the log to an external service here. This would typically involve some form of HTTP request or similar.

        LogEntry *temp = current;
        current = current->next;
        free(temp);
    }

    head = tail = NULL;

    pthread_mutex_unlock(&lock);
}
```
This code provides a basic logging framework. The `log` function adds new log entries to the end of a linked list, and each entry includes a timestamp, log level, and message. To handle potential memory leaks, we free up all memory associated with the log entries after sending them to an external service. Thread safety is achieved through use of a mutex lock.

