typedef struct {
    int id;
    char* status;
} Item;

typedef struct Node {
    Item* item;
    struct Node *next;
} DependencyNode;

DependencyNode* create_node(Item* item) {
    DependencyNode* newNode = malloc(sizeof(DependencyNode));

    if (newNode == NULL) {
        return NULL;
    }

    // Deep copy of the status string is necessary to avoid memory problems. 
    char* newStatus = malloc(strlen(item->status) + 1);
    strcpy(newStatus, item->status);

    Item* newItem = malloc(sizeof(Item));

    if (newItem == NULL) {
        free(newNode);
        return NULL;
    }

    newItem->id = item->id;
    newItem->status = newStatus;
    newNode->item = newItem;
    newNode->next = NULL;

    return newNode;
}
```
