    printf("%s: %s\n", log->level, log->message);

    pthread_mutex_unlock(&lock);  // Release lock
}

void runBackgroundCommand(char* command) {
    pid_t pid = fork();

    if (pid == 0) {  // Child process
        system(command);
        exit(EXIT_SUCCESS);
    } else if (pid < 0) {
        printf("Fork failed!\n");
    } else {
        wait(NULL);  // Parent waits for child to finish.
    }
}

