```javascript
import fetch from 'node-fetch'; // Use node-fetch for server-side fetching, or just use built-in fetch in browser env

// A cache object for storing script objects
let scriptCache = {};

async function renderFooterScripts(scriptObjects) {
    let htmlString = '';

    for (const script of scriptObjects) {
        const {src, type = "text/javascript", async = false, defer = false} = script; // Default values provided if not defined in object

        // Skip if already processed or in cache to handle unique scripts and optimizing for memory
        if (scriptCache[src]) continue; 

        try {
            const response = await fetch(src, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/javascript',
                    // Add any necessary authentication tokens or other headers here
                }
            });

            if (response.ok) {
                scriptCache[src] = true; 

                const scriptTag = `<script src="${src}" type="${type}" ${async ? 'async' : ''} ${defer ? 'defer' : ''}></script>`;

                htmlString += scriptTag; // Concatenate the HTML string to return 
            } else {
                console.error(`Fetch failed with status: ${response.status} and message: ${response.statusText} for script source: ${src}`);
            }
        } catch (err) {
            console.log('Error fetching scripts', err);
        }
    }

    return htmlString;
}
``` 

This function loops over an array of script objects, constructs `<script>` tags based on the object's properties, and adds them to a string which is returned at the end. It checks if the script source has already been processed (in cache) to avoid duplicates and optimize for memory usage. 

Note: In a production environment, it's recommended to use a robust caching solution like Redis or Memcached in order to handle large scale distributed systems effectively and ensure consistency across multiple servers. This example uses an object as a simple way of demonstrating the concept without adding unnecessary complexity.
