use tracing::info;

#[derive(Debug, Deserialize)]
struct BuildReport {
    // ... fields describing the build report
}

lazy_static::lazy_static ref CLIENT: reqwest::Client = reqwest::Client::new();

pub struct BuildManager {
    profiles: HashMap<String, String>,  // project_name -> profile
    cache: Option<HashMap<String, BuildReport>>,
}

impl BuildManager {
    pub async fn start(&self) {
        for (project, profile) in &self.profiles {
            let report = self.get_report(project, profile).await;
            // store the report
        }
    }

    async fn get_report(&self, project: &str, profile: &str) -> BuildReport {
        if let Some(cached_report) = self.cache.get(project) {
            return cached_report;
        }

        info("Fetching build report for project={}, profile={}", project, profile);
        match CLIENT.get(format::build_url(project, profile)).send().await {
            Ok(resp) => {
                let report: BuildReport = resp.json().await?;
                self.cache.insert(project.to_owned(), report);
                return report;
            },
            Err(_e) => {
                // handle the error (including distributed tracing)
            }
        }
    }
}
```
