['It's quite challenging to achieve all these features in one go. This kind of application would require deep knowledge about Rust programming language, cloud storage APIs, concurrent systems, networking, machine learning etc. 

I will try to sketch out the overall structure of the code but keep in mind that this is just a starting point and not a complete solution:

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use std::net::TcpStream;
use serde_json::Value;
use reqwest;

// Define a struct to hold the file transfer info
struct FileTransfer {
    source: String,
    destination: String,
}

// A worker thread that will do the file transfer
fn worker(file_queue: Arc<Mutex<Vec<FileTransfer>>>) {
    loop {
        let mut queue = file_queue.lock().unwrap();
        if let Some(transfer) = queue.pop() {
            // perform file transfer
            do_transfer(transfer);
        } else {
            thread::sleep(Duration::from_secs(1));
        }
    }
}

fn do_transfer(transfer: FileTransfer) {
    // read data from source 
    let data = std::fs::read(&transfer.source).unwrap();

    // write data to destination
    std::fs::write(&transfer.destination, &data).unwrap();
}

fn main() {
    // initialize the file transfer queue
    let file_queue = Arc::new(Mutex::new(Vec::new()));

    // spawn 100 worker threads
    for _ in 0..100 {
        thread::spawn(move || worker(file_queue.clone()));
    }

    let file = FileTransfer {
        source: "source_path".to_string(),
        destination: "destination_path".to_string(),
    };

    // push a file transfer task into the queue
    *file_queue.lock().unwrap() = vec![file];
}
```
