['Designing such a complex library in C++ is beyond the scope of this platform as it involves multiple tasks that are quite extensive. However, I can provide a basic skeleton for an encryption/decryption library using C++ standard libraries that you could expand upon to fulfill your requirements. 

```cpp
#include <iostream>
#include <string>
#include <openssl/aes.h>
#include <openssl/evp.h>

class AESEncryption {
private:
    unsigned char key[AES_BLOCK_SIZE];
    AES_KEY enc_key, dec_key;
public:
    AESEncryption(const std::string &key) {
        for (size_t i = 0; i < sizeof(this->key); ++i) {
            this->key[i] = static_cast<unsigned char>(key.at(i % key.length()));
        }

        AES_set_encrypt_key(this->key, 128, &enc_key);
        AES_set_decrypt_key(this->key, 128, &dec_key);
    }

    std::string encrypt(const std::string &plain) {
        unsigned char in[AES_BLOCK_SIZE];
        unsigned char out[AES_BLOCK_SIZE];

        for (size_t i = 0; i < plain.length(); i += AES_BLOCK_SIZE) {
            for (size_t j = i; j < std::min(plain.length(), i + AES_BLOCK_SIZE); ++j) {
                in[j % AES_BLOCK_SIZE] = static_cast<unsigned char>(plain.at(j));
            }

            AES_encrypt(in, out, &enc_key);
        }

        return std::string((char*)out, AES_BLOCK_SIZE);
    }

    std::string decrypt(const std::string &cipher) {
        unsigned char in[AES_BLOCK_SIZE];
        unsigned char out[AES_BLOCK_SIZE];

        for (size_t i = 0; i < cipher.length(); i += AES_BLOCK_SIZE) {
            for (size_t j = i; j < std::min(cipher.length(), i + AES_BLOCK_SIZE); ++j) {
                in[j % AES_BLOCK_SIZE] = static_cast<unsigned char>(cipher.at(j));
            }

            AES_decrypt(in, out, &dec_key);
        }

        return std::string((char*)out, AES_BLOCK_SIZE);
    }
};
```

This code is just a simplified example of an encryption/decryption library. It uses the OpenSSL library for handling the actual AES operations and it only supports 128-bit keys (AES-128). You would need to expand upon this example to fulfill all your requirements, including multi-threading, real-time network conditions handling, integration with external Key Management Services, metadata tagging, logging, machine learning model for dynamic algorithm selection etc. These tasks are quite extensive and cannot be fully demonstrated in a small code block here.
