  return new Promise((resolve, reject) => {
    fileStream.on('data', (chunk) => {
      shasum.update(chunk);
    });

    fileStream.on('end', () => {
      let hash = shasum.digest('hex');
      cache[filename] = hash; // Update the local cache
      resolve(hash);
    });

    fileStream.on('error', (err) => {
      reject(err);
    });
  });
}

