```cpp
#include <atomic>
#include <functional>
#include <map>
#include <vector>
#include <shared_mutex>

template<typename EventType>
class EventBus {
public:
    typedef std::function<void(EventType const&)> Handler;

    void subscribe(Handler handler) {
        std::lock_guard<std::shared_timed_mutex> lock(_subscribeMutex);
        _handlers.push_back(handler);
    }

    void publish(EventType event) const {
        // Acquire a shared lock to allow concurrent reads, but not writes or erasures.
        std::shared_lock<std::shared_timed_mutex> lock(_subscribeMutex);
        for (auto& handler : _handlers) {
            handler(event);
        }
    }

private:
    mutable std::vector<Handler> _handlers;
    mutable std::shared_timed_mutex _subscribeMutex;
};
