```cpp
#include <functional>
#include <map>
#include <vector>
#include <mutex>
#include <typeindex>

class Event {
public:
    virtual ~Event() {}
};

class ListenerBase {
public:
    virtual ~ListenerBase() {}
};

template<typename T, typename EventType>
class Listener : public ListenerBase {
public:
    typedef void (T::*MemberFunction)(const EventType&);
    Listener(T* instance, MemberFunction member)
        : instance_(instance), member_(member) {}

    void call(const EventType& event) const {
        (instance_->*member_)(event);
    }
private:
    T* instance_;
    MemberFunction member_;
};

class EventBus {
public:
    template<typename EventType>
    void broadcast(const EventType& event) const {
        std::lock_guard<std::mutex> lock(listenersMutex_);
        for (auto listener : listeners_[typeid(EventType)]) {
            static_cast<Listener<void, EventType>*>(listener)->call(event);
        }
    }

    template<typename T, typename EventType>
    void addEventListener(T* instance, void (T::*member)(const EventType&)) {
        std::lock_guard<std::mutex> lock(listenersMutex_);
        listeners_[typeid(EventType)].push_back(new Listener<T, EventType>(instance, member));
    }

private:
    mutable std::map<std::type_index, std::vector<ListenerBase*>> listeners_;
    mutable std::mutex listenersMutex_;
};
```
This is a very simple and basic implementation. It doesn't take into account many of the advanced topics you asked about like thread safety, performance, scalability, system integration with microservices frameworks etc. Each topic requires deep research into their own fields and extensive coding to implement properly which goes beyond this single response limit.
