```php
<?php
namespace Lib;
use Exception;
use RuntimeException;

class Security {
    private $entropySource = 'random_bytes';
    private $fallbackSources = [
        ['source' => 'openssl', 'function' => 'openssl_random_pseudo_bytes'],
        ['source' => 'mcrypt', 'function' => 'mcrypt_create_iv']
    ];

    public function generateRandomString($length) {
        $string = '';

        while (($len = strlen($string)) < $length) {
            $size = $length - $len;

            try {
                $bytes = call_user_func($this->entropySource, $size);
            } catch (Exception $e) {
                foreach ($this->fallbackSources as $source) {
                    if (!function_exists($source['function'])) {
                        continue;
                    }

                    $bytes = call_user_func($source['function'], $size);

                    if (is_string($bytes)) {
                        $this->entropySource = $source['source'];
                        break;
                    }
                }
            }

            $string .= substr(str_replace(['/', '+', '='], '', base64_encode($bytes)), 0, $size);
        }

        return $string;
    }

    public function hashPassword($password) {
        $options = [
            'cost' => 12, // Adjust the cost factor as needed
        ];

        return password_hash($password, PASSWORD_BCRYPT, $options);
    }
}
?>
