struct HTTP_REQUEST_PDU_T {
    // Your data here.
};

class RequestProcessor {
public:
    void processRequest(HTTP_REQUEST_PDU_T request) {
        std::lock_guard<std::mutex> lock(mtx);
        requests.push(request);
        cv.notify_one();
    }

private:
    std::queue<HTTP_REQUEST_PDU_T> requests;
    std::condition_variable cv;
    std::mutex mtx;
};

class RequestService {
public:
    void start() {
        running = true;
        serviceThread = std::thread(&RequestService::serviceLoop, this);
    }

    void stop() {
        if(running) {
            running = false;
            processor.processRequest({}); // Dummy request to wake up the thread.
            serviceThread.join();
        }
    }

    void processRequest(HTTP_REQUEST_PDU_T request) {
        processor.processRequest(request);
    }

private:
    void serviceLoop() {
        while (running) {
            HTTP_REQUEST_PDU_T request = getNextRequest();
            // Process the request here...

            if(!running) return;
        }
    }

    HTTP_REQUEST_PDU_T getNextRequest() {
        std::unique_lock<std::mutex> lock(processor.mtx);

        while (processor.requests.empty()) {
            processor.cv.wait(lock);

            if(!running) return {};
        }

        HTTP_REQUEST_PDU_T request = processor.requests.front();
        processor.requests.pop();
        return request;
    }

private:
    RequestProcessor processor;
    std::thread serviceThread;
    bool running;
};
```
To handle errors, you would need to add try-catch blocks and logging, which is not shown here for simplicity. Furthermore, this code does not include all the features mentioned in your request such as memory pool allocation, dependency management, concurrency control etc. It's a starting point but for a fully functional production service, much more work would be required.
