int do_crypt(unsigned char* input, int inputlen, unsigned char* output, const EVP_CIPHER* cipher) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if(1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) handleErrors();

    if(1 != EVP_EncryptUpdate(ctx, output, &len, input, inputlen)) handleErrors();
    ciphertext_len = len;

    if(1 != EVP_EncryptFinal_ex(ctx, output + len, &len)) handleErrors();
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}
