```rust
use tokio::net::lookup_host;
use std::collections::HashMap;

struct DnsSystem {
    cache: HashMap<String, String>,
}

impl DnsSystem {
    async fn resolve(&mut self, host: &str) -> Result<String, Box<dyn std::error::Error>> {
        if let Some(ip) = self.cache.get(host) {
            return Ok(ip.clone());
        }

        // Resolve host using tokio
        let ips = lookup_host(host, &[], 32).await?;

        let ip = ips.into_iter().next().unwrap();

        self.cache.insert(host.to_string(), ip);

        Ok(ip)
    }
}
```

2. **Concurrent Lookups**: Rust's async/await syntax can be used to handle multiple concurrent lookups. 

