['```go
// This is a simplified version of how you might implement such a system. Actual implementation would be much more complex.

package rate_limiter

import (
	"sync/atomic"
	"time"
)

type RateLimiter struct {
	limit           int64
	burstSize       int64
	granularity    time.Duration
	currentRequests atomic.Int64
}

func NewRateLimiter(limit, burstSize int, granularity time.Duration) *RateLimiter {
	return &RateLimiter{
		int64(limit),
		int64(burstSize),
		granularity,
		atomic.Int64{},
	}
}

func (r *RateLimiter) Limit() bool {
	if r.currentRequests.Load() >= r.limit {
		return false
	}

	// This is a simplification of the actual logic. In reality, you would use something like a token bucket algorithm to smooth out spikes in traffic and ensure fairness. 
	r.currentRequests.Add(1)
	time.AfterFunc(r.granularity, func() {
		r.currentRequests.Add(-1)
	})
	return true
}
```
This basic rate limiter implementation ensures that no more than the specified number of requests can be made within a time window (which is determined by `granularity`), with some allowance for bursts above this limit. The `Limit()` function checks if we're currently under our request limit, and if so, increases the current request count and schedules a decrement operation to run after the granularity period has passed.

