```java
import org.springframework.http.*;
import org.springframework.web.client.RestTemplate;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.stream.*;

class MetadataService {
    private static final RestTemplate restTemplate = new RestTemplate();
    private static final String METADATA_SERVICE_URL = "http://metadata-service/api/v1/data";

    public CompletableFuture<Integer> getDisjointPairs(int[] arr) {
        return CompletableFuture.supplyAsync(() -> 
            IntStream.of(arr).distinct().count()
        );
    }

    public CompletableFuture<Double> getMedian(int[] arr) {
        int[] sortedArr = Arrays.stream(arr).sorted().toArray();
        return CompletableFuture.supplyAsync(() -> 
            arr.length % 2 == 0 ? (sortedArr[arr.length / 2] + sortedArr[(arr.length / 2) - 1]) / 2.0 : sortedArr[arr.length / 2]
        );
    }

    public CompletableFuture<Integer> getMode(int[] arr) {
        return CompletableFuture.supplyAsync(() -> 
            Arrays.stream(arr).boxed().collect(Collectors.groupingBy(Function.identity(), Collectors.counting())).entrySet()
                .stream().max(Map.Entry.comparingByValue()).map(Map.Entry::getKey).orElse(null)
        );
    }

    public CompletableFuture<Integer> getMetadataFromService(int[] arr){
        HttpHeaders headers = new HttpHeaders();
        headers.setBearerAuth(token); // replace with real token handling

        HttpEntity<int[]> entity = new HttpEntity<>(arr, headers);

        return restTemplate.exchange(METADATA_SERVICE_URL, HttpMethod.POST, entity, Integer.class)
            .thenApply(ResponseEntity::getBody);
    } 
}
```
This code assumes that the external metadata service is capable of computing disjoint pairs, median and mode for an array of integers via a POST request to METADATA_SERVICE_URL with an array in the body. It also needs OAuth2 token handling which is not implemented in this sample. You may use Spring's Oauth2RestTemplate or any other OAuth library for secure communication with your external service.
