['Below is an example of how you might approach designing such a library in Python. The following implementation uses threading for concurrent processing, logging framework for auditing, OAuth2Session for API calls, and json for deserialization. Please modify it according to your specific requirements:

```python
import logging
from requests_oauthlib import OAuth2Session
from threading import Thread
import json
import time

class StreamLogProcessor(object):
    def __init__(self, token, logstreams, deserialization_factories=None, cache_size=1000, logger=None):
        self.oauth = OAuth2Session(token=token)
        self.logstreams = logstreams
        self.deserialization_factories = deserialization_factories or {}
        self.cache = []
        self.cache_size = cache_size
        self.logger = logger or logging.getLogger(__name__)

    def register(self, schema, factory):
        self.deserialization_factories[schema] = factory

    def process(self, stream):
        while True:
            try:
                response = self.oauth.get(stream)
                for log in response.iter_lines():
                    if len(self.cache) >= self.cache_size:
                        self._flush()
                    self.cache.append(json.loads(log))
            except Exception as e:
                self.logger.error("Error processing stream %s: %s", stream, str(e))

    def _flush(self):
        for log in self.cache:
            schema = log["schema"]
            if schema in self.deserialization_factories:
                try:
                    deserialized_log = self.deserialization_factories[schema](log)
                    # Further processing...
                except Exception as e:
                    self.logger.error("Error deserializing log with schema %s: %s", schema, str(e))
            else:
                self.logger.warning("No factory registered for schema %s", schema)
        self.cache = []

    def start_processing(self):
        threads = [Thread(target=self.process, args=(stream,)) for stream in self.logstreams]
        for thread in threads:
            thread.start()
