void streamProcessTextChunks() {
    // Assume we're receiving JSON strings from the streaming API
    std::vector<std::string> jsonStrings = {"{\"payload\":\"Hello, world\"}", "{\"payload\":\"This is a test\"}"};

    std::thread threads[jsonStrings.size()]; // Create an array of threads

    for (int i = 0; i < jsonStrings.size(); ++i) {
        threads[i] = std::thread([&, i] { // Start a new thread
            auto j = json::parse(jsonStrings[i]); // Parse the JSON string into a json object

            if (j.find("payload") != j.end()) {
                std::string payload = j["payload"]; // Extract the payload field
                std::cout << transformPayload(payload) << "\n"; // Transform and print the payload
            } else {
                std::cerr << "No 'payload' field found in JSON object!\n";
            }
        });
    }

    for (auto& th : threads) {
        th.join();  // Join all threads
    }
}
```
This code uses a thread-per-task model, which is a simple and common approach to concurrency in C++. It parses each JSON string into a `nlohmann::json` object (a class provided by the nlohmann/json library), extracts the payload field, applies a transformation function to it, and then prints the result to standard output. 

