The header file includes necessary libraries and defines a structure `OAuth2Handler` for the main object. It provides prototypes for functions to create, destroy, and process requests:

```c
/* oauth2_handler.c */
#include "oauth2_handler.h"

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    json_object *jobj = json_tokener_parse((char*) contents);
    userp = jobj;  /* We're saving the received JSON into userp */
    return realsize;
}

OAuth2Handler* oauth2_handler_create(const char *url) {
    OAuth2Handler *handler = malloc(sizeof(OAuth2Handler));
    handler->curl = curl_easy_init();
    curl_easy_setopt(handler->curl, CURLOPT_URL, url);
    curl_easy_setopt(handler->curl, CURLOPT_WRITEFUNCTION, write_callback);
    return handler;
}

void oauth2_handler_destroy(OAuth2Handler *handler) {
    curl_easy_cleanup(handler->curl);
    free(handler);
}

json_object* oauth2_handler_process_request(OAuth2Handler *handler) {
    CURLcode res = curl_easy_perform(handler->curl);
    if(res != CURLE_OK)
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    return handler->response;
}
```
In the implementation file we have a callback function `write_callback` for processing the incoming data from the network request and save it into our structure. The `oauth2_handler_create` function initializes the CURL library, sets some options (like URL to connect to), and prepares to handle the response with the write callback function.

