void DataGenerator::generateAndInsert() {
    std::uniform_real_distribution<double> dist(minValue_, maxValue_);

    curlpp::Cleanup myCleanup; // This will ensure the cleanup of all CURL resources, even in case of errors.

    for (int i = 0; i < recordCount_; ++i) {
        double val = dist(rng_);

        try {
            curlpp::Easy request;

            // Set options on the easy handle using a list of tuple
            std::list<std::string> header; 
            header.push_back("Content-Type: application/json");

            request.setOpt(new curlpp::options::Url("http://example.com")); 
            request.setOpt(new curlpp::options::HttpHeader(header)); 
            request.setOpt(new curlpp::options::PostFields("{\"value\":" + std::to_string(val) + "}"));
            request.setOpt(new curlpp::options::PostFieldSize(0)); // This means the POST data is exactly this size, regardless of content.

            request.perform(); // Perform the request.
        } catch (curlpp::RuntimeError &e) {
            std::cerr << "RuntimeError: " << e.what() << std::endl;
        } catch (curlpp::LogicError &e) {
