public class SecureHashService : ISecureHashService
{
    private readonly IConnectionMultiplexer _redis; // Redis client
    private readonly ILogger<SecureHashService> _logger;

    public SecureHashService(IConnectionMultiplexer redis, ILogger<SecureHashService> logger) 
    {
        this._redis = redis;
        this._logger = logger;
    }

    // Example method to generate and cache MD5 hash
    public async Task<string> GetMD5Hash(string input, CancellationToken cancellationToken)
    {
        var db = _redis.GetDatabase();

        try 
        {
            // Try to get the hash from Redis first
            string cachedHash = await db.StringGetAsync(input);
            if (cachedHash != null)
                return cachedHash;

            using var md5 = MD5.Create();
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            string hash = Convert.ToHexString(hashBytes); // convert to hexadecimal for readability

            // Cache the result in Redis
            await db.StringSetAsync(input, hash);

            return hash;
        } 
        catch (Exception ex) when (!cancellationToken.IsCancellationRequested)
        {
            _logger.LogError(ex, "Failed to generate or cache MD5 hash");
            throw;
        }
    }

