// Define a memory pool for reusing integer arrays
struct MemoryPool {
    int* data;
    size_t capacity;
};

typedef struct {
    char *memory;
    size_t size;
} Buffer;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct Buffer *mem = (struct Buffer *)userp;

    mem->memory = realloc(mem->memory, mem->size + realsize + 1);
    if(mem->memory == NULL) {
        /* out of memory */ 
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

struct MemoryPool *initialize_pool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(*pool));
    if (pool == NULL) {
        // handle error
        return NULL;
    }

    pool->data = calloc(capacity, sizeof(*pool->data));
    if (pool->data == NULL) {
        // handle error
        free(pool);
        return NULL;
    }
    pool->capacity = capacity;
    return pool;
}

void destroy_pool(struct MemoryPool *pool) {
    free(pool->data);
    free(pool);
}

