typedef struct {
    int key;
    long offset;
    char* randomString;
} Record;

Record* records = NULL;
size_t recordCount = 0;
pthread_mutex_t lock;

void* readInitialData(void* args) {
    // Simulate reading data from external source.
    records = malloc(10 * sizeof(Record));
    recordCount = 10;

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].key = i;
        records[i].offset = i * 10;
        records[i].randomString = "Random String"; // Replace this with your actual data
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Mutex initialization failed.\n");
        return 1;
    }

    pthread_t threadId;
    int result = pthread_create(&threadId, NULL, &readInitialData, NULL);

    if (result != 0) {
        printf("Thread creation failed.\n");
        return 1;
    }

    pthread_mutex_lock(&lock);
    pthread_mutex_unlock(&lock); // This will block until readInitialData completes

    json_value* recordsJson = json_array();
    for (size_t i = 0; i < recordCount; ++i) {
        json_object* obj = json_object();
        json_add_int(obj, "key", records[i].key);
        json_add_long(obj, "offset", records[i].offset);
