        json_array_push(recordsJson, obj);
    }

    // Persist to distributed database with retry logic and error handling.
    printf("%s\n", json_serialize(recordsJson));

    pthread_join(threadId, NULL);
    pthread_mutex_destroy(&lock);
    free(records);
}
