            element.addEventListener(eventType, handler);
        });

        this.eventHandlers.push({ selector, eventType, handler });
    }

    cacheDOMStructure(name, structure) {
        if (!this.cachedDOMStructures.has(name)) {
            this.cachedDOMStructures.set(name, structure);
        } else {
            console.warn("Already cached DOM structure with the name " + name);
        }
    }

    getCachedDOMStructure(name) {
        if (this.cachedDOMStructures.has(name)) {
            return this.cachedDOMStructures.get(name);
        } else {
            console.error("No cached DOM structure with the name " + name);
        }
    }

    registerServiceWorker(sw) {
        if (typeof sw === 'function') {
            this.serviceWorker = new sw();
        } else {
            console.error("Invalid service worker");
        }
    }

    logPerformanceMetric(metric, value) {
        if (!this.performanceMetrics[metric]) {
            console.warn("Unrecognized performance metric: " + metric);
            return;
        }

        this.performanceMetrics[metric].push({ timestamp: Date.now(), value });
    }

    getPerformanceMetric(metric) {
        if (!this.performanceMetrics[metric]) {
            console.error("Unrecognized performance metric: " + metric);
            return;
        }

        return this.performanceMetrics[metric];
    }
}
