async fn monitor_update(url: &str) -> Result<(), Box<dyn std::error::Error>> {
    let resp = reqwest::get(url).await?;
    if resp.status().is_success() {
        println Кorrect API response has been received!");
        Ok(())
    } else {
        Err("Incorrect API response was received.")?
    }
}

#[tokio::main]
