    let mut watch = watch::watch();

    tokio::spawn(async move {
        loop {
            if let Ok(()) = monitor_update("https://api.example.com/updates").await {
                *watch.borrow_mut() += 1;
            } else {
                println Incorrect API response was received.";
            }

            tokio::time::sleep(Duration::from_secs(5)).await;
        }
    });

    loop {
        let snapshot = watch.read();
        println Number of successful updates: {}", snapshot);

        tokio::time::sleep(Duration::from_secs(10)).await;
