#include <openssl/aes.h>
#include <string.h>
#include <stdio.h>

int main(void) {
    unsigned char key[AES_BLOCK_SIZE];        // AES-128 (16 bytes), AES-192 (24 bytes), or AES-256 (32 bytes)
    unsigned char iv[AES_BLOCK_SIZE];         // init vector
    memset(iv, 0, AES_BLOCK_SIZE);             // if you don't want to use IV then all zeros

    const unsigned char data[] = "Hello, world!";
    int len = sizeof(data);

    printf("Original text:\n%s\n", data);

    AES_KEY aesKey;
    if (AES_set_encrypt_key(key, 128 /* key length in bits */, &aesKey) < 0) {
        fprintf(stderr, "Could not create encryption key\n");
        return -1;
    }

    unsigned char encrypted[len];
    AES_cbc_encrypt(data, encrypted, len, &aesKey, iv, AES_ENCRYPT); // Encrypt
    printf("Encrypted:\n%s\n", encrypted);

    if (AES_set_decrypt_key(key, 128 /* key length in bits */, &aesKey) < 0) {
        fprintf(stderr, "Could not create decryption key\n");
        return -1;
    }

    unsigned char decrypted[len];
    AES_cbc_encrypt(encrypted, decrypted, len, &aesKey, iv, AES_DECRYPT); // Decrypt
    printf("Decrypted:\n%s\n", decrypted);
}
```

