// Define the structure for a CRC Indication record
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG[10];
} CRCIndicationRecord;

// Define the log framework data structure
typedef struct {
    pthread_mutex_t mutex;
    PGconn *dbConnection;
    int nextIndex;
    CRCIndicationRecord records[10000];
} LogFrameworkData;

LogFrameworkData *logFrameworkData = NULL;
pthread_once_t initOnceControl = PTHREAD_ONCE_INIT;
PGconn* dbConnection = NULL;

// Initialize the log framework data structure
void initializeLogFramework() {
    if (logFrameworkData == NULL) {
        // Allocate memory for the data structure
        logFrameworkData = malloc(sizeof(LogFrameworkData));

        // Initialize mutex
        pthread_mutex_init(&logFrameworkData->mutex, NULL);
        logFrameworkData->dbConnection = dbConnection;
        logFrameworkData->nextIndex = 0;
    }
}

// Log a CRC indication record to the framework data structure
void logCRCIndicationRecord(CRCIndicationRecord *record) {
    // Ensure the log framework has been initialized
    pthread_once(&initOnceControl, initializeLogFramework);

    // Acquire lock for thread safety
    pthread_mutex_lock(&logFrameworkData->mutex);

    // Check if records array is full
    if (logFrameworkData->nextIndex < 10000) {
        memcpy(&logFrameworkData->records[logFrameworkData->nextIndex], record, sizeof(CRCIndicationRecord));
        logFrameworkData->nextIndex++;
    } else {
        printf("Maximum number of records reached!\n");
    }

    // Release lock
    pthread_mutex_unlock(&logFrameworkData->mutex);
}
``` 
