        entry->message = logMessage;

        pthread_t thread;
        pthread_create(&thread, NULL, addLogEntry, (void*)entry);
    }

    // Wait for all threads to finish...
    for(int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
