typedef struct {
    unsigned char* key;
    AES_KEY enc_key, dec_key;
} aes256_context;

// Function to initialize the aes context with the given key
int aes256_init(aes256_context* ctx, const unsigned char* key, size_t length) {
    int nrounds = 5;
    unsigned char* k = (unsigned char*)malloc(length);
    memcpy(k, key, length);

    if(AES_set_encrypt_key(k, 256, &ctx->enc_key) < 0 || 
       AES_set_decrypt_key(k, 256, &ctx->dec_key) < 0){
        return -1;
    }

    ctx->key = k;
    return 0;
}

// Function to encrypt the given data with AES-256
unsigned char* aes256_encrypt(aes256_context* ctx, unsigned char* data) {
    size_t len = strlen((char*)data);
    unsigned char cipher[128];

    AES_ecb_encrypt(data, cipher, &ctx->enc_key, 1);

    return cipher;
}

// Function to decrypt the given data with AES-256
unsigned char* aes256_decrypt(aes256_context* ctx, unsigned char* cipher) {
    size_t len = strlen((char*)cipher);
    unsigned char text[128];

    AES_ecb_encrypt(cipher, text, &ctx->dec_key, 0);

    return text;
}

// This function will be called from a different thread to copy bytes and return them in a new buffer.
unsigned char* copyBytes(const unsigned char* source, size_t offset, size_t length) {
    if (offset >= strlen((char*)source))
        return NULL;

    unsigned char* result = malloc(length);
    memcpy(result, source + offset, length);

    return result;
}
```

For JavaScript part:
```Javascript
function copyBytes(dataChunks, start, end) {
  // dataChunks is assumed to be an array of Node.js Buffer objects
  var totalLength = end - start;
  var bufferResult = new Buffer(totalLength);

  for (var i = 0; i < dataChunks.length; i++) {
    // Check if this chunk contains part or all of the desired bytes
    if ((start < (i + 1) * BUFFER_SIZE && end > i * BUFFER_SIZE)) {
      var startIndex = Math.max(0, start - i * BUFFER_SIZE);
      var endIndex = Math.min((i + 1) * BUFFER_SIZE, end) - i * BUFFER_SIZE;

      dataChunks[i].copy(bufferResult, 0, startIndex, endIndex);
    }
  }

  return bufferResult;
}
```

