#include <openssl/err.h>
#include <pthread.h>

// Thread-safe lock for multithreaded environment
static pthread_mutex_t *locks;

void locking_function(int mode, int n, const char *file, int line) {
    if (mode & CRYPTO_LOCK) {
        pthread_mutex_lock(&(locks[n]));
    } else {
        pthread_mutex_unlock(&(locks[n]));
    }
}

void thread_id_function(CRYPTO_THREADID *id) {
    CRYPTO_THREADID_set_numeric(id, (unsigned long)pthread_self());
}

int main() {
   // Initialize locks for multithreaded environment
    locks = OPENSSL_malloc(CRYPTO_num_locks() * sizeof(pthread_mutex_t)); 

    for (int i = 0; i < CRYPTO_num_locks(); i++) {
        pthread_mutex_init(&(locks[i]), NULL);
    }

    // Register locking functions and thread id function
    CRYPTO_THREADID_set_callback(thread_id_function);
    CRYPTO_set_locking_callback(locking_function);

   // Use OpenSSL library here...
}
