    public:
        std::atomic<OctreeNode*> root;

        bool insert(float point[3]) {
            if (!root) return false;
            // Root node is full span of 3D space.
            return insertIntoSubtree(point, root.load(), {-1,-1,-1}, {1,1,1});
        }

        bool remove(float point[3]) {
            if (!root) return false;
            // Root node is full span of 3D space.
            deleteFromSubtree(point, root.load(), {-1,-1,-1}, {1,1,1});
        }
};
