from abc import ABC, abstractmethod
from typing import Any

class Ingestor(ABC):
    @abstractmethod
    def ingest(self) -> Any:
        pass

class Egressor(ABC):
    @abstractmethod
    def egress(self, data: Any):
        pass

class Transformer(ABC):
    @abstractmethod
    def transform(self, data: Any) -> Any:
        pass

class DataPipeline:
