['Here's an initial outline for a C++ library that meets your requirements. This is by no means exhaustive or fully functional code, but it provides a starting point.

```cpp
#include <thread>
#include <future>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <stdexcept>
#include <iostream>

class BackgroundTask {
public:
    virtual void run() = 0;
};

template<typename R>
class FutureBackgroundTask : public BackgroundTask {
public:
    std::future<R> get_future() { return promise.get_future(); }
protected:
    std::promise<R> promise;
};

// Implement a concrete background task, e.g., one that fetches data from an API
class FetchDataTask : public FutureBackgroundTask<std::string> {
public:
    FetchDataTask(const std::string& url) : url(url) {}

    void run() override {
        // Simulate fetching data, in a real-world scenario this might be an HTTP request
        promise.set_value("Some Data from " + url);
    }
private:
    std::string url;
};

class ThreadPool {
public:
    explicit ThreadPool(size_t threadCount) : shutdown_(false) {
        for (size_t i = 0; i < threadCount; ++i) {
            threads_.emplace_back([this]() { worker(); });
        }
    }

    ~ThreadPool() {
        shutdown();
    }

    void submit(std::shared_ptr<BackgroundTask> task) {
        std::unique_lock<std::mutex> lock{mutex_};
        tasks_.push(task);
        cv.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::shared_ptr<BackgroundTask> task;
            {
                std::unique_lock<std::mutex> lock{mutex_};
                cv.wait(lock, [this](){ return shutdown_ || !tasks_.empty(); });
                if (shutdown_) break;
                task = tasks_.front();
                tasks_.pop();
            }
            try {
                task->run();
            } catch (const std::exception& e) {
                // Handle errors here, e.g., log them and move on to the next task
                std::cerr << "Task execution failed: " << e.what() << '\n';
            }
        }
    }

    void shutdown() {
        {
            std::unique_lock<std::mutex> lock{mutex_};
            shutdown_ = true;
        }
        cv.notify_all();
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    std::vector<std::thread> threads_;
    std::queue<std::shared_ptr<BackgroundTask>> tasks_;
    std::mutex mutex_;
    std::condition_variable cv;
    bool shutdown_;
};
```
In this code, we define an abstract `BackgroundTask` class that encapsulates a task to be run in the background. We also provide a concrete subclass of `BackgroundTask`, `FetchDataTask`, which fetches data from an API.

The `ThreadPool` class represents our thread pool. It spawns a number of worker threads (specified by the user) and assigns tasks to them as they become available. If a task throws an exception, it is caught and logged before moving on to the next task. The pool can be shut down cleanly using `std::condition_variable` to notify all idle workers when the shutdown flag becomes true.
']

