['Here's a simplified example of how you might implement such a function using C language. This is a skeleton code and doesn't cover all the features listed in your request due to the complexity involved in implementing them. However, it provides an idea of how these features could be structured into a modular C library:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// This struct will represent individual nodes in our Union-Find data structure
typedef struct {
    int parent;  // index of the parent node
    int rank;  // used for union by rank
} Subset;

int find(Subset subsets[], int i) {
    if (subsets[i].parent != i)
        subsets[i].parent = find(subsets, subsets[i].parent);

    return subsets[i].parent;
}

void Union(Subset subsets[], int x, int y) {
    int xroot = find(subsets, x);
    int yroot = find(subsets, y);

    if (subsets[xroot].rank < subsets[yroot].rank)
        subsets[xroot].parent = yroot;
    else if (subsets[xroot].rank > subsets[yroot].rank)
        subsets[yroot].parent = xroot;
    else {
        subsets[yroot].parent = xroot;
        subsets[xroot].rank++;
    }
}

// Function to check if a pair is disjoint
int isDisjoint(Subset subsets[], int x, int y) {
    return find(subsets, x) != find(subsets, y);
}

// Count the number of disjoint pairs in an array
int countPairs(int arr[], int n) {
    int i, j;

    // Initialize n subsets for n elements
    Subset* subsets = (Subset*) malloc(n * sizeof(Subset));

    for (int v = 0; v < n; ++v) {
        subsets[v].parent = v;
        subsets[v].rank = 0;
    }

    // Iterate through all pairs and check for disjointness.
    int count = 0;
    clock_t start, end; 
    double cpu_time_used;

    for(i=0; i<n-1; i++) {
        for(j=i+1; j<n; j++) {
            start = clock();

            if (isDisjoint(subsets, arr[i], arr[j])) {
                count++;  // increase count if disjoint pair found

                Union(subsets, arr[i], arr[j]);  // merge sets containing the two elements
            }

            end = clock();
            cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
            printf("Time taken for pair %d and %d: %f milliseconds\n", arr[i], arr[j], cpu_time_used*1000);  // print time taken for each pair
        }
    }

    free(subsets);
    return count;
}
```
The function `countPairs` accepts an array and its size as input, creates a subset for every element in the array using a Union-Find data structure, checks all pairs of elements if they form a disjoint set or not and counts them. The time taken to check each pair is also printed out. 

Please note that this code does not have any error handling mechanisms and doesn't integrate with any external services as requested in the original problem. It simply demonstrates how you can use Union-Find data structure for checking disjointness of pairs from a given array. This code will need to be further expanded, integrated into an existing library or application, and tested to meet all requirements mentioned in your request.
