class BufferCopy {
  constructor(sourceBuffers) {
    this.sourceBuffers = sourceBuffers;
  }

  copyBytes(numBytesToCopy) {
    let copiedBytesCount = 0;
    const newBuffer = Buffer.allocUnsafe(numBytesToCopy);

    for (const buffer of this.sourceBuffers) {
      if (copiedBytesCount < numBytesToCopy) {
        const bytesLeftToCopy = numBytesToCopy - copiedBytesCount;

        // Determine how much can be copied from the current buffer, up to bytesLeftToCopy or until the end of the buffer
        const bytesAvailableInBuffer = Math.min(bytesLeftToCopy, buffer.length);

        // Copy from the buffer into newBuffer at the appropriate position
        buffer.copy(newBuffer, copiedBytesCount, 0, bytesAvailableInBuffer);

        // Update the count of copied bytes
        copiedBytesCount += bytesAvailableInBuffer;
      } else {
        break;
      }
    }

    if (copiedBytesCount < numBytesToCopy) {
      console.warn(`Warning: Could only copy ${copiedBytesCount} out of the requested ${numBytesToCopy} bytes.`);
