function copyBufferData(sourceBuffers, bytesToCopy) {
    let copiedBytes = 0;
    const destinationBuffer = Buffer.allocUnsafe(bytesToCopy);

    sourceBuffers.forEach((buffer) => {
        if (copiedBytes === bytesToCopy) return;

        // Copy from the current buffer to the destination buffer
        buffer.copy(destinationBuffer, copiedBytes, 0, copiedBytes + buffer.length);
        copiedBytes += buffer.length;
    });

    return destinationBuffer;
}
