import threading
from abc import ABC, abstractmethod

class DataStream:
    def __init__(self):
        self._observers = []

    def register_observer(self, observer):
        self._observers.append(observer)

    def notify_observers(self, data):
        for observer in self._observers:
            observer.update(data)

class DataStreamObserver(ABC):
    @abstractmethod
    def update(self, data):
        pass

class IoTDeviceDataSource(DataStream):
    def __init__(self):
        super().__init__()

    # connect to device and fetch data
    def fetch_data(self):
        # mock data
        data = {'device': 'IoT Device', 'value': 123}
        self.notify_observers(data)

class DataEnricher(DataStreamObserver):
    def update(self, data):
        print("Enriching data")

        # enrich the data
        enriched_data = {'enriched': True}

        self.notify_observers(enriched_data)

class DataProcessor(DataStreamObserver):
    def update(self, data):
        print("Processing data")

# Usage
if __name__ == "__main__":
    # Initialize IoT device and enricher
    iot_device = IoTDeviceDataSource()
    enricher = DataEnricher()
    processor = DataProcessor()

    # Register observers
    iot_device.register_observer(enricher)
    enricher.register_observer(processor)

```
