    public DataTable ExecuteSecureBatchInsert(List<object> data, SqlConnection connection, string commandString)
    {
        if (connection == null || connection.State != ConnectionState.Open)
            throw new ArgumentException("Invalid SQL connection");

        var table = new DataTable(); // Assuming a return type of DataTable here for the sake of example. 

