using System;
using System.Security.Cryptography;
using StackExchange.Redis;
using Microsoft.Extensions.Options;

public class HashService : IHashService
{
    private readonly IDatabase _cache;
    private readonly AuthApiClient _authApiClient;
    private readonly UserManagementServiceClient _userMgmtClient;
    private readonly IdentityProviderClient _idpClient;
    private readonly HashOptions _options;

    public HashService(IOptions<HashOptions> optionsAccessor, ConnectionMultiplexer redis)
    {
        if (redis == null) throw new ArgumentNullException(nameof(redis));

        _cache = redis.GetDatabase();
        // Initialize clients to interact with other services
        _authApiClient = new AuthApiClient(optionsAccessor.Value.AuthApiUrl);
        _userMgmtClient = new UserManagementServiceClient(optionsAccessor.Value.UserManagementServiceUrl);
        _idpClient = new IdentityProviderClient(optionsAccessor.Value.IdentityProviderUrl);

        // Initialize options
        _options = optionsAccessor.Value;
    }

    public async Task<string> GetHashAsync(string username, string password)
    {
        var cacheKey = $"hash:{username}";
        var cachedHash = await _cache.StringGetAsync(cacheKey);

        if (cachedHash != default) return (string)cachedHash;

        using var sha256 = SHA256.Create();
        var passwordBytes = System.Text.Encoding.UTF8.GetBytes(password);
        var hashBytes = await sha256.ComputeHashAsync(new MemoryStream(passwordBytes));
        var hashString = Convert.ToBase64String(hashBytes);

        // Cache the hash with an expiration time
        await _cache.StringSetAsync(cacheKey, hashString, TimeSpan.FromMinutes(_options.CacheExpiryInMinutes));

        return hashString;
    }
}
```

