async fn update(api: &str, token: Option<&str>) {
    let client = match api {
        "cloud-based" => cloud_client(token), // Your implementation to interact with the API
        "third-party" => third_party_client(token), // Your implementation to interact with the API
        _ => panic![], // Handle unsupported APIs
