#include <mutex>
#include <random>

namespace RandomGenerator {
    class MersenneTwister {
        private: 
            static std::mt19937 mt; // Engine
            static std::mutex mutex; // Mutex for thread-safety
            static bool seeded; // Check if seeded or not

        public: 
            MersenneTwister(unsigned int seed = 0) {
                std::lock_guard<std::mutex> lock(mutex);

                // Seed only once in multi-threaded environment
                if(!seeded) {
                    if(seed != 0) mt.seed(seed); 
                    else mt.seed(std::random_device{}());
                    seeded = true;
                }
            }

            // Generate random numbers for different data types
            int getRandomInt() { return std::uniform_int_distribution<int>{}(mt); }
            double getRandomDouble() { return std::uniform_real_distribution<double>{}(mt); }

            template <typename T> 
            void fillUniform(T begin, T end) { 
                std::lock_guard<std::mutex> lock(mutex);
                std::generate(begin, end, [&](){return getRandomDouble();}); 
            }
    };

    // Initialize static members
    bool MersenneTwister::seeded = false;
    std::mt19937 MersenneTwister::mt;
    std::mutex MersenneTwister::mutex; 
}
