```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

// Define structs as per your requirement. For simplicity, I have defined only the required fields.
typedef struct CryptoFunction {
    const char* name;
    void* handle;
    int (*hash_or_cipher)(void*, const void*, size_t, void*);
    size_t param_size;
} CryptoFunction;

// Global cryptographic function array and mutex.
static CryptoFunction** cryptoFunctions = NULL;
static pthread_mutex_t lock;

void init_crypto_nfaapi_pdu(int providerCount, const char* (*getProviderName)(int), void* (*initProviderHandle)(const char*, int)) {
    // Initialize mutex.
    if (atomic_load(&lock) == 0) {
        pthread_mutex_init(&lock, NULL);
    }

    // Lock the mutex to ensure thread-safety.
    pthread_mutex_lock(&lock);

    // Check if cryptoFunctions is already initialized. If it is, we don't need to redo the initialization.
    if (cryptoFunctions != NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Allocate memory for cryptographic function array.
    cryptoFunctions = malloc(providerCount * sizeof(CryptoFunction*));

    // Initialize each provider and its corresponding handle.
    for (int i = 0; i < providerCount; ++i) {
        const char* providerName = getProviderName(i);
        void* providerHandle = initProviderHandle(providerName, i);

        if (providerHandle != NULL) {
            cryptoFunctions[i] = malloc(sizeof(CryptoFunction));

            // Assign respective values to each CryptoFunction struct.
            cryptoFunctions[i]->name = providerName;
            cryptoFunctions[i]->handle = providerHandle;
            // Here you need to assign hash_or_cipher, param_size based on your requirement.

        } else {
            // Handle error situation when a handle is NULL. You may want to try another provider or fall back.
            free(cryptoFunctions);
            cryptoFunctions = NULL;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Unlock the mutex after initialization.
    pthread_mutex_unlock(&lock);
}
``` 

This is a basic implementation of `init_crypto_nfaapi_pdu` function which initializes cryptographic function structures for multiple providers in a thread-safe manner. The specifics of the initialization process will depend on the details of your use case and may require additional error handling, fallback mechanisms, and other features you mentioned.
