["Below is a simplified example of what the code could look like:

```javascript
const fs = require('fs').promises;
const globby = require('globby');
const pMap = require('p-map');
const logger = require('./loggerService'); // Implement your own logging service

class FileProcessor {
  constructor(directory, pattern) {
    this.directory = directory;
    this.pattern = pattern;
  }

  async processDirectory() {
    const paths = await globby([this.pattern], { cwd: this.directory });

    return pMap(paths, path => this.processFile(path), { concurrency: 10 });
  }

  async processFile(filePath) {
    try {
      const content = await fs.readFile(`${this.directory}/${filePath}`, 'utf8');
      logger.log('success', `Successfully read file ${filePath}`);

      return { filename: filePath, content };
    } catch (error) {
      logger.log('failure', `Failed to read file ${filePath}. Reason: ${error.message}`);

      throw new Error(`Error processing file ${filePath}: ${error.message}`);
    }
  }
}

module.exports = FileProcessor;
```
This code uses Node's built-in `fs` and `globby` modules for asynchronous file system operations. The `pMap` module is used to limit concurrency (10 in this case), which avoids consuming excessive memory or CPU resources when dealing with large directories.

To ensure efficient logging, a hypothetical loggerService is integrated that provides a method like `logger.log(type, message)`. 

