["Here is an implementation of dynamicScriptLoader function, considering the given constraints:

```javascript
// Define the base URL and parameters
const baseURL = 'https://api.example.com/scripts';
const params = {
  async: true,
  defer: false,
};

function dynamicScriptLoader(scriptObjects) {
  const scriptQueue = []; // Queue for scripts to be loaded

  function loadScript(index = 0) {
    if (index >= scriptQueue.length) { // Base case of recursion
      return Promise.resolve();
    }

    const scriptObject = scriptObjects[scriptQueue[index]];
    const scriptElement = document.createElement('script');

    for (const [key, value] of Object.entries(params)) { // Add parameters to the script element
      if (typeof value === 'function') {
        scriptElement[key] = value;
      } else {
        scriptElement.setAttribute(key, value);
      }
    }

    scriptElement.src = scriptObject.src; // Add src to the script element

    return new Promise((resolve, reject) => {
      scriptElement.onload = resolve;
      scriptElement.onerror = () => reject(new Error(`Failed to load script ${scriptObject.scriptId}`));

      document.head.appendChild(scriptElement); // Append the script element to the head of the document
    })
      .then(() => {
        console.log(`Script ${scriptObject.scriptId} loaded successfully`);

        return loadScript(index + 1); // Recursive case, loading next script
      })
      .catch((error) => {
        console.warn(error);

        if (scriptObject.dependencies && scriptObject.dependencies.length > 0) { // If dependencies exist, add them to the queue
          scriptQueue.push(...scriptObject.dependencies);
        }

        return loadScript(index + 1);
      });
  }

  scriptObjects.forEach(({ scriptId }) => {
    if (document.getElementById(scriptId)) { // If the script is already in the document, skip it
      return;
    }

    scriptQueue.push(scriptId);
  });

  loadScript();
}
```
This function creates `<script>` elements based on the given objects and appends them to the head of the HTML document. It uses Promises for managing asynchronous loading, handles errors, and recursively loads scripts in order. It checks if a script is already present in the document before adding it to the queue to avoid duplicates.
"]

