}

class LogIngestionService implements Runnable {

    private final BlockingQueue<LogEntry> queue = new LinkedBlockingQueue<>();
    private ExecutorService executor = Executors.newFixedThreadPool(10); // 10 threads for log processing

    @Override
    public void run() {
        while (true) {
            try {
                LogEntry entry = queue.take();
                executor.execute(() -> processLog(entry));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void processLog(LogEntry entry) {
        // Process the log here...
    }
}

public class Main {
