using json = nlohmann::json;

void streamProcessTextChunks() {
    // Load environment variables with API keys, etc.
    const std::string apiKey = std::getenv("API_KEY");

    // Initialize buffer and allocators for efficient memory management
    std::vector<char> buffer(1024); 
    json j;

    while (true) {
        try {
            // Fetch log entries from the streaming API, handling retries and fallbacks with exponential backoff.
            // You would typically use a library like libcurl for this.
            std::string logEntry = fetchLogEntry(apiKey); 

            // Parse and process the log entry using nlohmann::json
            j = json::parse(logEntry); 

            // Perform custom transformation on payload string
            const std::string transformedPayload = transformPayload(j["payload"]); 

            // Asynchronously compress the log entry before sending over network
            auto handle = std::async(std::launch::async, [transformedPayload]() {
                return compressLogEntry(transformedPayload);
            });

            // Store compressed log entry in a buffer
            buffer.push_back(handle.get()); 
        } catch (const std::exception& e) {
            std::cerr << "Error processing log entry: " << e.what() << '\n';
            continue;
        }
    }
}

int main() {
    // Use a thread to handle API requests concurrently, adjust for your specific requirements
    std::thread t(streamProcessTextChunks); 
    t.join();
    return 0;
}
```

Please note that you will need to implement all helper functions (fetchLogEntry(), transformPayload() and compressLogEntry()) according to the actual API usage. Also, this is a high-level sketch and may not compile or work directly in your environment as it's missing some crucial parts of the implementation.
