int main() {
  std::ifstream input("input.txt");
  std::ofstream output("output.txt");
  std::string line;

  while (std::getline(input, line)) {
    std::vector<double> numbers;
    double num;
    std::istringstream iss(line);

    // read and parse the numbers from this line
    while (iss >> num) {
      numbers.push_back(num);
