CURL *get_easy_handle() {
    CURL *curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        // Set other options here...
    }
    return curl;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct string *s = (struct string *)userp;

    char *ptr = realloc(s->ptr, s->len + realsize + 1);
    if(!ptr) {
        /* out of memory */ 
        return 0;
    }

    s->ptr = ptr;
    memcpy(&(s->ptr[s->len]), contents, realsize);
    s->ptr[new_len] = '\0';
    s->len += realsize;

    return realsize;
}
```
This will allow us to make HTTP requests and process the responses.

Next, let's define a function to fetch JSON data from an API:

```c
json_t *fetch_json(const char* url) {
    CURL *curl = get_easy_handle();
    if (curl) {
        struct string s;
        init_string(&s);

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        curl_easy_setopt(curl, CURLOPT_URL, url);

        /* Perform the request */ 
        res = curl_easy_perform(curl);

        /* Check for errors */ 
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return NULL;
        }

        json_error_t error;
        json_t *root = json_loads(s.ptr, 0, &error);
        free_string(&s);

        /* Make sure the root is an object */ 
        if (!json_is_object(root)) {
            fprintf(stderr, "JSON response is not an object\n");
            json_decref(root);
            return NULL;
        }

        curl_easy_cleanup(curl);
        return root;
    }

    /* Return NULL on failure */ 
    return NULL;
}
```
This function will fetch a URL, parse the returned JSON, and return it.

