// Use npm or yarn to install it

// Define your own configurations
const config = {};
config.allowedFileTypes = [/* List of allowed file types */];

const app = express();
app.use(express.json());

let currentProviderIndex = 0;
const storageProviders = [new Storage() /*, ... */]; // define your providers here

function getStorageProvider(){
  const provider = storageProviders[currentProviderIndex++ % storageProviders.length];

  return {
    uploadFileFromURL: async (url, bucketName) => {
      const response = await axios({ method:'get', url, responseType:'stream' });

      const storage = new Storage();
      const bucket = storage.bucket(bucketName);
      const file = bucket.file('myFile');

      return new Promise((resolve, reject) => {
        response.data.pipe(file.createWriteStream())
          .on('finish', () => resolve())
          .on('error', (e) => reject(e));
      });
    }
  };
}

app.post('/uploadFileFromURL', async (req, res) => {
  const provider = getStorageProvider();

  try{
    await provider.uploadFileFromURL(req.body.url, req.body.bucketName);
    res.status(200).send('Upload successful');
  }catch(e){
    console.error('Failed to upload file', e);
    res.status(500).send('Failed to upload the file');
  }
});
```

This is a simple example of how you can setup an express server that receives a POST request with url and bucket name, and then tries to upload this file from this URL using one of your storage providers, cycling through them in order. In real world application, the logic behind choosing which provider to use would be more complex, based on various factors such as cost, geographical location, load, etc. You would also need to add proper input validation and error handling for edge cases. 

