npm install crypto-js node-fetch dotenv express
```

Next, write JavaScript code in `index.js` to process logs and hash files concurrently:

```javascript
const express = require('express');
const crypto = require('crypto-js');
const fetch = require('node-fetch').default;
require('dotenv').config();

const app = express();
app.use(express.json());

// Sample log data format - adjust based on actual log structure
let logs = [{ file: 'file1', hashAlgorithm: 'SHA256' }, { file: 'file2', hashAlgorithm: 'MD5' }];

app.get('/hashFiles', async (req, res) => {
    // Process each log asynchronously
    const promises = logs.map(async (log) => {
        try {
            // Fetch file from external API or local storage
            const response = await fetch('https://example.com/' + log.file);
            if (!response.ok) throw new Error('HTTP error ' + response.status);
            const buffer = await response.buffer();

            let hash;
            // Compute hash based on specified algorithm
            switch (log.hashAlgorithm) {
                case 'SHA256':
                    hash = crypto.SHA256(buffer).toString();
                    break;
                case 'MD5':
                    hash = crypto.MD5(buffer).toString();
                    break;
            }

            return { file: log.file, hash };
        } catch (error) {
            console.log('Error processing', log.file, ':', error);
            return { file: log.file, error: error.message };
        }
    });

    // Await all promises and return results
    const results = await Promise.all(promises);
    res.json({ hashes: results });
});

app.listen(3000, () => console.log('Server started on port 3000'));
```

In terms of caching and fallback strategy, you'd need to implement those parts manually as they would require a deeper understanding of your specific use case and infrastructure. This implementation is also incomplete in that it does not handle file I/O operations or deal with metadata APIs for files. Implementing these features will require further research on how to read from disk, manage data store, etc., which are beyond the scope of this question's complexity.
