public class DatabaseService : IDatabaseService
{
    private readonly IConfiguration _configuration;
    private readonly ILogger<DatabaseService> _logger;

    public DatabaseService(IConfiguration configuration, ILogger<DatabaseService> logger)
    {
        _configuration = configuration;
        _logger = logger;
    }

    // Use the factory pattern to create database connections
    private IDbConnection CreateConnection() 
    {
        var connectionString = _configuration.GetConnectionString("DefaultConnection");

        return new SqlConnection(connectionString);
    }

    public async Task<T> GetAsync<T>(string sql, object param = null)
    {
        using (var conn = CreateConnection())
        {
            try
            {
                // Use Dapper for querying the database as it is fast and safe.
                return await conn.QueryFirstOrDefaultAsync<T>(sql, param);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Database Error");

                throw;
            }
        }
    }

    // Add similar methods for Update, Delete, etc.
}
```
