```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <future>

class MigrationManager {
public:
    void startMigrations() {
        // Start migrations in multiple threads
        std::vector<std::future<void>> futures;
        for (int i = 0; i < databases.size(); ++i) {
            futures.push_back(std::async(&Database::migrate, databases[i]));
        }

        // Wait for all migrations to complete
        for (auto &future : futures) {
            future.get();
        }
    }

private:
