Next, we will compute the MD5 hash of a string and for larger files:
```java
import java.io.*;
import java.security.*;
import java.nio.file.*;

public class HashCalculator {

    public String calculateMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());

        BigInteger no = new BigInteger(1, messageDigest);
        String hashtext = no.toString(16);
        while (hashtext.length() < 32) {
            hashtext = "0" + hashtext;
        }

        return hashtext;
    }

    public String calculateMD5ForLargeFile(String filePath) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");

        try (InputStream is = Files.newInputStream(Paths.get(filePath));
            DigestInputStream dis = new DigestInputStream(is, md)) {

            while (dis.read() != -1) {}

            byte[] digest = md.digest();

            return DatatypeConverter.printHexBinary(digest).toUpperCase();
        }
    }
}
```
