['Here is the code to securely load a state object from a file using an ObjectInputStream. This code includes input validation and exception handling.

```java
import java.io.*;
import java.security.MessageDigest;
import javax.xml.bind.DatatypeConverter;

public class SecurityUtils {
    private static final String ALGORITHM = "MD5";

    public static Object loadSecurely(String filename) throws Exception {
        // Ensure the filename is not null or empty
        if (filename == null || filename.isEmpty()) {
            throw new IllegalArgumentException("Filename cannot be null or empty.");
        }

        // Compute the MD5 hash of the filename
        MessageDigest md = MessageDigest.getInstance(ALGORITHM);
        byte[] digest = md.digest(filename.getBytes());
        String fileHash = DatatypeConverter.printHexBinary(digest).toLowerCase();

        // Validate the filename hash to prevent unauthorized access
        if (!isValidFilenameHash(fileHash)) {
            throw new SecurityException("Unauthorized access: invalid filename hash.");
        }

        ObjectInputStream in = null;
        try {
            FileInputStream fileIn = new FileInputStream(filename);
            in = new ObjectInputStream(fileIn);
            return in.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new Exception("Error loading securely: " + e.getMessage());
        } finally {
            if (in != null) {
                try {
                    in.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private static boolean isValidFilenameHash(String fileHash) {
        // TODO: Implement the logic to validate the filename hash. This could involve comparing it with a whitelist or a blacklist of valid hashes, for example.
        return true;
    }
}
