void logError(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Allocate buffer for log message
    size_t length = vsnprintf(NULL, 0, format, args);
    char* buffer = malloc((length + 1) * sizeof(char));

    if (!buffer) {
        va_end(args);
        return;
    }

    // Write log message to buffer and print it
    vsnprintf(buffer, length + 1, format, args);
    printf("%s\n", buffer);

    free(buffer);
    va_end(args);
}
```
To use this function:
```c
int main() {
    logError("An error occurred: %d", 42);
    return 0;
}
```
