['Creating such a complex system would be beyond the scope of this platform due to several factors like complexity, size and many others. However, I can provide a basic starting point for your code in C. The Rust function you mentioned about compiling another Rust binary falls under domain of build automation and is not directly related to creating dynamic pools of structures.

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    void* CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

atomic_uint next_index = 0;
NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void init_pool(size_t size) {
    pthread_mutex_init(&pool_lock, NULL);
    pool = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int get_index() {
    return atomic_fetch_add(&next_index, 1) % (next_index / sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void* add_session(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool_lock);
    int index = get_index();
    if (pool[index].RX_UE_INFORMATION_TAG == 0 && pool[index].RNTI == 0 && pool[index].CRC_INDICATION_REL8_TAG == NULL) {
        pool[index] = *pdu;
        pthread_mutex_unlock(&pool_lock);
        return &(pool[index]);
    } else {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Or handle differently based on your requirements
    }
}

void remove_session(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool_lock);
    for (size_t i = 0; i < next_index / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        if (&(pool[i]) == pdu) {
            pool[i].RX_UE_INFORMATION_TAG = 0;
            pool[i].RNTI = 0;
            pool[i].CRC_INDICATION_REL8_TAG = NULL;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}
```
The above code only provides a basic starting point and does not include error handling, proper synchronization between threads or other complex features that would be needed in a production system. Please note that working with 50,000 concurrent sessions in C can be quite challenging and might require specific design considerations, such as using efficient data structures for managing multiple sessions concurrently.
