import asyncio
from abc import ABC, abstractmethod
from pandas import DataFrame

class StreamProcessor(ABC):
    @abstractmethod
    def process_stream(self, stream) -> DataFrame:
        pass

class CSVStreamProcessor(StreamProcessor):
    def process_stream(self, stream) -> DataFrame:
        # Implementation here...
        pass

class JSONStreamProcessor(StreamProcessor):
    def process_stream(self, stream) -> DataFrame:
        # Implementation here...
        pass

# Add other StreamProcessors for different formats

class DataStreamer:
    def __init__(self, processor: StreamProcessor):
        self.processor = processor

    async def ingest(self, stream) -> DataFrame:
        # This can be extended to include caching and error handling
        return await asyncio.to_thread(self.processor.process_stream, stream)
```

