```c
#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>

int resolve_dns(const char *hostname, u_char ip[4]) {
    struct addrinfo hints = {0}, *res = NULL;
    int errcode;
    void *ptr;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(hostname, NULL, &hints, &res);

    if (errcode != 0) {
        perror("DNS resolution failed");
        return -1; // Return Error Code on failure
    }

    while (res) {
        switch (res->ai_family) {
            case AF_INET: 
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                break;
            default:
                printf("Unknown address family\n");
                return -1; // Return Error Code on failure
        }

        inet_ntop(res->ai_family, ptr, ip, 16); // Assuming IPV4 only as per the problem statement. For handling IPv6 and other formats, you may need to modify this part accordingly.

        res = res->ai_next;
    }

    freeaddrinfo(res);

    return 0; // Return Success on DNS resolution
}
```
Please note that, this is a very basic example and does not handle some edge cases. You might want to consider handling edge cases like non-existing hostname or multiple IP addresses etc. Also, you need to add error checking mechanisms in the library functions as per your requirements. 

