using System;
using System.Data.SqlClient;
using System.IO;
using System.Threading;
using System.Collections.Concurrent;
using System.Runtime.Serialization.Formatters.Binary;

public class EmployeeService
{
    private static readonly Lazy<EmployeeService> instance = new(() => new EmployeeService());
    public static EmployeeService Instance => instance.Value;

    // Thread-safe dictionary to store employee data in memory
    private ConcurrentDictionary<string, Employee> _employeesCache;
    private BinaryFormatter formatter = new BinaryFormatter();

    private EmployeeService() 
    {
        LoadEmployeeDataFromFile("path_to_your_file");
    }

    public (List<Employee>, List<Supervisor>) FilterAndFetch(List<string> supervisorsIds)
    {
        var filteredEmployees = _employeesCache.Values.Where(e => supervisorsIds.Contains(e.SupervisorId)).ToList();
        return (filteredEmployees, FetchSupervisorDetailsFromDb(supervisorsIds));
    }

    private List<Supervisor> FetchSupervisorDetailsFromDb(List<string> supervisorsIds)
    {
        var result = new List<Supervisor>();

        using (SqlConnection connection = new SqlConnection("your_connection_string"))
        {
            connection.Open();

            foreach (var id in supervisorsIds)
            {
                using (SqlCommand command = new SqlCommand($"SELECT * FROM Supervisors WHERE Id=@Id", connection))
                {
                    command.Parameters.AddWithValue("@Id", id);

                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            result.Add(new Supervisor 
                            {
                                Id = reader["Id"].ToString(),
                                Name = reader["Name"].ToString()
                                // Add other properties here
                            });
                        }
                    }
                }
            }
        }

        return result;
    }

    private void LoadEmployeeDataFromFile(string path) 
    {
        try
        {
            using (Stream stream = File.Open(path, FileMode.Open))
            {
                _employeesCache = (ConcurrentDictionary<string, Employee>)formatter.Deserialize(stream);
            }
        }
        catch (IOException ex) 
        {
            // Log exception and rethrow
            throw;
        }
    }
}
```

