import org.springframework.cache.annotation.Cacheable;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.web.bind.annotation.*;

import java.io.File;
import java.net.URL;

@RestController
public class FileUploadController {

    @Autowired
    private ThirdPartyService thirdPartyService;

    @Cacheable(value = "files", key="#fileUrl")
    @Retryable(value = Exception.class, maxAttemptsExpression = "#{${retry.maxAttempts}}", backoff = @Backoff(delayExpression = "#{${retry.maxDelay}}"))
    public File uploadFile(@RequestParam String fileUrl) throws Exception {
        URL url = new URL(fileUrl);

        try {
            return thirdPartyService.uploadFile(url);
        } catch (Exception e) {
            throw new RuntimeException("Error while trying to upload file", e);
        }
    }
}
```

