const axios = require('axios');
const FormData = require('form-data');
const fs = require('fs');

async function uploadFile(fileUrl, thirdPartyServiceUrl) {
    const fileStream = fs.createReadStream(fileUrl);

    const formData = new FormData();
    formData.append('file', fileStream);

    try {
        const response = await axios.post(thirdPartyServiceUrl, formData, {
            headers: formData.getHeaders()
        });

        return response;
    } catch (error) {
        console.log('Error while trying to upload file', error);
    }
}
```
This function uses axios library for HTTP requests and FormData to handle files in multipart/form-data format, which is often used by APIs for uploading files. The function will also handle errors gracefully with a try-catch block, providing detailed error information.
