// Secure session storage for tokens
export function setAccessToken(token) {
    sessionStorage.setItem(accessTokenKey, token);
}

export async function authenticateUser() {
    const url = 'https://oauthprovider/token';
    const params = new URLSearchParams();
    params.append('grant_type', 'client_credentials');
    const config = { headers: { Authorization: `Basic ${Buffer.from(`${process.env.CLIENT_ID}:${process.env.CLIENT_SECRET}`).toString('base64')}` } };

    try {
        const response = await axios.post(url, params, config);
        setAccessToken(response.data.access_token);
    } catch (error) {
        throw new Error("Authentication failed");
    }
}

export async function uploadFileWithOAuth(filePath) {
    const accessToken = sessionStorage.getItem(accessTokenKey);

    if (!accessToken) {
        await authenticateUser();
    }

    let retries = 0;
    while (retries < maxRetries) {
        try {
            return await uploadFile(filePath, accessToken);
        } catch (error) {
            if (isRateLimitError(error)) {
                console.log('Rate limit exceeded. Retrying...');
                retries++;
                // Exponential backoff strategy
                await sleep(retryDelay * Math.pow(2, retries));
            } else {
                throw error;
            }
        }
    }

    throw new Error("Maximum retries exceeded");
}

async function uploadFile(filePath, accessToken) {
    const url = 'https://fileservice/upload';
    let formData = new FormData();
    formData.append('file', fs.createReadStream(filePath));

    try {
        return await axios.post(url, formData, { headers: { Authorization: `Bearer ${accessToken}` } });
    } catch (error) {
        throw new Error("File upload failed");
    }
}

function isRateLimitError(error) {
    return error.response && error.response.status === 429; // 429: Too Many Requests
}

// Function to wait for a certain time period
async function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}
```

