```javascript
const express = require('express');
const multer = require('multer');
const AWS = require('aws-sdk');
const uuidv4 = require('uuid').v4;
require('dotenv').config();

AWS.config.update({
  region: process.env.AWS_REGION,
  accessKeyId: process.env.AWS_ACCESS_KEY_ID,
  secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
});

const s3 = new AWS.S3();
const upload = multer({ storage: multer.memoryStorage() });

const app = express();

app.post('/upload', upload.single('file'), async (req, res) => {
  try {
    const fileExtension = req.file.originalname.split('.').pop();
    const params = {
      Bucket: process.env.AWS_BUCKET_NAME,
      Key: `${uuidv4()}.${fileExtension}`, // Unique filename
      Body: req.file.buffer,
    };

    const data = await s3.upload(params).promise();
    res.status(201).json({
      message: 'File uploaded successfully',
      fileUrl: data.Location, // URL of the file in S3 bucket
    });
  } catch (error) {
    console.log(error);
    res.sendStatus(500);
  }
});

app.listen(process.env.PORT || 8080, () => {
  console.log('Server is running on port 8080');
});
```
This code uses AWS SDK to upload files to an S3 bucket. You would need to replace the placeholders with your actual AWS configurations and S3 bucket name. The 'file' parameter in `upload.single` is the key that should be used for file uploads (in this case, it would be a multipart form data). 

