#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int device_id;
    char **feature_set_versions;
    int status_code;
} DEVICE_STATE_UPDATE_PDU_T;

DEVICE_STATE_UPDATE_PDU_T *batch_update_device_states(int num_devices, int *device_ids, char ***feature_sets, int *status_codes) {
    DEVICE_STATE_UPDATE_PDU_T *updates = malloc(num_devices * sizeof(DEVICE_STATE_UPDATE_PDU_T));

    for (int i = 0; i < num_devices; ++i) {
        updates[i].device_id = device_ids[i];

        // Copy feature sets and status codes. You may need to adjust this based on your actual needs.
        int num_features = sizeof(feature_sets[i]) / sizeof(char*);
        updates[i].feature_set_versions = malloc(num_features * sizeof(char*));

        for (int j = 0; j < num_features; ++j) {
            int len = strlen(feature_sets[i][j]) + 1;
            updates[i].feature_set_versions[j] = malloc(len);
            strcpy(updates[i].feature_set_versions[j], feature_sets[i][j]);
        }

        updates[i].status_code = status_codes[i];
    }

    return updates;
}
```

This is a basic implementation that assumes the caller will free `updates` and its members when they're no longer needed. A more robust version might use reference counting or garbage collection to automatically release memory, but this would add considerable complexity. 

