#include <pthread.h>
#define MAX_BUFFER_SIZE 1024 // Define maximum buffer size for circular buffer

typedef struct {
    /* Packet Data */
} MEDIA_STREAM_PACKET_T;

MEDIA_STREAM_PACKET_T buffer[MAX_BUFFER_SIZE];
int head = 0, tail = 0, count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread synchronization

void processMediaStreamingPackets(MEDIA_STREAM_PACKET_T packet) {
    pthread_mutex_lock(&mutex); // Lock mutex to ensure mutual exclusion while accessing shared data

    if (count == MAX_BUFFER_SIZE) { // If buffer is full, drop packet and log error
        /* Logging code */

        return;
    }

    // Process the media packet here. If necessary, forward it to an external service for decoding/encoding

    buffer[tail] = packet; // Add new packet into the buffer
    tail = (tail + 1) % MAX_BUFFER_SIZE; // Update tail index in a circular way
    count++; // Increment count of packets in the buffer

    pthread_mutex_unlock(&mutex); // Unlock mutex so other threads can access shared data
}
```
This code creates a circular buffer to store media packets. When adding a packet, it checks if the buffer is full before adding more items. If so, it logs an error and returns without adding the packet. 

