```cpp
#include <random>
#include <mutex>

class RandomGenerator {
private:
    std::mt19937_64 gen; // This uses Mersenne Twister engine, a good PRNG.
    std::uniform_int_distribution<uint64_t> dis; // Uniform distribution for integers.
    std::mutex mtx; // For thread safety.
public:
    RandomGenerator() {
        std::random_device rd;
        gen = std::mt19937_64(rd());
        dis = std::uniform_int_distribution<uint64_t>(0, UINT64_MAX); // Initialize distribution.
    }

    uint64_t next() {
        std::lock_guard<std::mutex> lock(mtx); // Ensure thread-safety.
        return dis(gen); // Return a random number from the generator.
    }
};
```

